impl Mapper for Bmc299 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x8000).max(1);
        self.prg
            .get((usize::from(self.prg32) % banks) * 0x8000 + usize::from(address - 0x8000))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.write_reg(value);
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        self.chr
            .get((usize::from(self.chr8) % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        if let Some(byte) = self
            .chr
            .get_mut((usize::from(self.chr8) % banks) * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        299
    }
}

/// MMC3 clone (mapper 254) with a scrambled WRAM read-back latch.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mmc3_254 {
    inner: Mmc3,
    unlocked: bool,
    xor: u8,
}

impl Mmc3_254 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            inner: Mmc3::new_as(prg, chr, header, 254),
            unlocked: false,
            xor: 0,
        }
    }
}

impl Mapper for Mmc3_254 {
    fn prg_read(&self, address: u16) -> u8 {
        if (0x6000..=0x7FFF).contains(&address) {
            let value = self.inner.prg_read(address);
            return if self.unlocked {
                value
            } else {
                value ^ self.xor
            };
        }
        self.inner.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x8000 => self.unlocked = true,
            0xA001 => self.xor = value,
            _ => {}
        }
        self.inner.prg_write(address, value);
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.inner.chr_read(address)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        self.inner.chr_write(address, value);
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        254
    }

    fn prg_ram(&self) -> &[u8] {
        &self.inner.prg_ram
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }
}

