impl Mapper for LatchAddr585 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let prg_bank = usize::from(self.addr) >> 1;
        if self.addr & 0x0001 != 0 {
            let banks = (self.prg.len() / 0x8000).max(1);
            let bank = (prg_bank >> 1) % banks;
            self.prg
                .get(bank * 0x8000 + usize::from(address - 0x8000))
                .copied()
                .unwrap_or(0)
        } else {
            let banks = (self.prg.len() / 0x4000).max(1);
            let bank = prg_bank % banks;
            let offset = if address < 0xC000 {
                usize::from(address - 0x8000)
            } else {
                usize::from(address - 0xC000)
            };
            self.prg.get(bank * 0x4000 + offset).copied().unwrap_or(0)
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        let _ = value;
        if address >= 0x8000 {
            self.addr = address;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = (usize::from(self.addr) >> 1) % banks;
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = (usize::from(self.addr) >> 1) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        if self.addr & 0x0010 != 0 {
            Mirroring::Vertical
        } else {
            Mirroring::Horizontal
        }
    }

    fn number(&self) -> u16 {
        585
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000
    }
}

/// Q-Ta CHR banking state shared with the PPU.
///
/// The name table byte at the current fetch position (`qt`) selects either a
/// CHR-ROM page (bit 6) or a 4 KiB CHR-RAM bank, and the mapper keeps a
/// private 2 KiB shadow name table that the game writes instead of CIRAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Qtram {
    /// Private shadow name table (`$D010` bit 0 set routes writes here).
    #[serde(with = "serde_big_array::BigArray")]
    pub ram: [u8; 0x800],
    /// Last tile byte read from the shadow table.
    pub qt: u8,
    /// Last nametable offset fetched (sprite-fetch heuristic).
    pub last_offset: u16,
    /// Whether the current pattern fetch belongs to a sprite.
    pub sprite: bool,
    /// `$D010` bit 0: name table writes go to [`Qtram::ram`].
    pub write_exram: bool,
    /// `$D010` bit 1 selects horizontal pairing of the shadow pages.
    pub horizontal: bool,
}

impl Qtram {
    fn new() -> Self {
        Self {
            ram: [0; 0x800],
            qt: 0,
            last_offset: 0,
            sprite: false,
            write_exram: false,
            horizontal: false,
        }
    }

    /// Records a name table fetch and latches the tile byte for CHR banking.
    pub fn note_read(&mut self, address: u16) {
        let offset = address & 0x3FF;
        if offset < 0x3C0 {
            // Vertical/horizontal selection is applied by the mapper's
            // mirroring mode: the 1 KiB quadrant index is enough here.
            let quadrant = usize::from(address >> 10 & 0x03);
            let page = if self.horizontal {
                quadrant >> 1
            } else {
                quadrant & 1
            };
            self.qt = self.ram[page * 0x400 + usize::from(offset)];
        }
        self.last_offset = offset;
    }
}

/// Konami Q-Ta educational computer (mapper 547): VRC5-style PRG/CHR
/// windows, 4 KiB work RAM at `$6000`/`$7000`, 16 registers at
/// `$D000-$DFFF`, a CPU-cycle IRQ counter and the JIS glyph lookup used by
/// the Q-Ta Kanji ROM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mapper547 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    reg: [u8; 16],
    qt: Rc<RefCell<Qtram>>,
    irq_counter: u16,
    irq_pending: bool,
}

impl Mapper547 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, _header: Header) -> Self {
        prg_ram.resize(0x40000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            reg: [0; 16],
            qt: Rc::new(RefCell::new(Qtram::new())),
            irq_counter: 0,
            irq_pending: false,
        }
    }

    fn prg_bank(reg: u8) -> usize {
        if reg & 0x40 != 0 {
            usize::from(reg & 0x3F) + 0x10
        } else {
            usize::from(reg & 0x0F)
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn ram_4k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg_ram.len() / 0x1000).max(1);
        self.prg_ram
            .get((bank % banks) * 0x1000 + usize::from(address & 0x0FFF))
            .copied()
            .unwrap_or(0)
    }

    /// Q-Ta JIS glyph lookup at `$DC00` (tile number) / `$DD00` (bank byte).
    fn glyph_read(&self, address: u16) -> u8 {
        const PAGE_TABLE: [u8; 0x24] = [
            0x0, 0x0, 0x2, 0x2, 0x1, 0x1, 0x4, 0x5, 0x6, 0x7, 0x8, 0x9, 0xA, 0xB, 0xC, 0xD, 0xE,
            0xF, 0x0, 0x1, 0x2, 0x3, 0x4, 0x5, 0x6, 0x7, 0x8, 0x9, 0xA, 0xB, 0xC, 0xD, 0xE, 0xF,
            0xD, 0xD,
        ];
        let row = self.reg[13].wrapping_sub(0x20);
        let col = self.reg[12].wrapping_sub(0x20);
        if row >= 0x60 || col >= 0x60 {
            return 0;
        }
        let code = u16::from(col % 32)
            + u16::from(row % 16) * 32
            + u16::from(col / 32) * 32 * 16
            + u16::from(row / 16) * 32 * 16 * 3;
        let glyph = (code & 0xFF) | (u16::from(PAGE_TABLE[usize::from(code >> 8) & 0x1F]) << 8);
        let tile = u32::from(glyph) * 4;
        if address == 0xDC00 {
            (tile as u8) | (self.reg[11] & 0x03)
        } else {
            ((tile >> 8) as u8) | if self.reg[11] & 0x04 != 0 { 0x80 } else { 0 } | 0x40
        }
    }
}

impl Mapper for Mapper547 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x6FFF => {
                let bank = usize::from(self.reg[0] & 1) | usize::from(self.reg[0] >> 2);
                self.ram_4k(bank, address)
            }
            0x7000..=0x7FFF => {
                let bank = usize::from(self.reg[1] & 1) | usize::from(self.reg[1] >> 2);
                self.ram_4k(bank, address)
            }
            0x8000..=0x9FFF => self.prg_8k(Self::prg_bank(self.reg[2]), address),
            0xA000..=0xBFFF => self.prg_8k(Self::prg_bank(self.reg[3]), address),
            0xDC00 | 0xDD00 => self.glyph_read(address),
            0xC000..=0xDFFF => self.prg_8k(Self::prg_bank(self.reg[4]), address),
            0xE000..=0xFFFF => self.prg_8k(0x4F, address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000..=0x6FFF => {
                let bank = usize::from(self.reg[0] & 1) | usize::from(self.reg[0] >> 2);
                let banks = (self.prg_ram.len() / 0x1000).max(1);
                self.prg_ram[(bank % banks) * 0x1000 + usize::from(address & 0x0FFF)] = value;
            }
            0x7000..=0x7FFF => {
                let bank = usize::from(self.reg[1] & 1) | usize::from(self.reg[1] >> 2);
                let banks = (self.prg_ram.len() / 0x1000).max(1);
                self.prg_ram[(bank % banks) * 0x1000 + usize::from(address & 0x0FFF)] = value;
            }
            0xD000..=0xDFFF => {
                let index = usize::from((address >> 8) & 0x0F);
                self.reg[index] = value;
                if index == 10 {
                    let mut qt = self.qt.borrow_mut();
                    qt.write_exram = value & 0x01 != 0;
                    qt.horizontal = value & 0x02 != 0;
                }
                match index {
                    8 => {
                        if self.reg[9] & 1 != 0 {
                            self.reg[9] |= 2;
                        } else {
                            self.reg[9] &= !2;
                        }
                        self.irq_pending = false;
                    }
                    9 => {
                        if self.reg[9] & 2 != 0 {
                            self.irq_counter =
                                u16::from(self.reg[6]) | (u16::from(self.reg[7]) << 8);
                        }
                        self.irq_pending = false;
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let qt = self.qt.borrow();
        if qt.qt & 0x40 != 0 {
            if address & 0x08 != 0 {
                return if qt.qt & 0x80 != 0 { 0xFF } else { 0x00 };
            }
            if self.chr.len() == 128 * 1024 {
                // The 128 KiB Q-Ta CHR-ROM dump has A0/A4 swapped and is
                // otherwise halved.
                let mut full = (u32::from(qt.qt & 0x3F) << 12)
                    | (u32::from(address >> 10 & 0x03) << 10)
                    | u32::from(address & 0x3FF);
                full = ((full & 0x000_0007) << 1)
                    | ((full & 0x000_0010) >> 4)
                    | ((full & 0x003_FFE0) >> 1);
                return self.chr.get(full as usize).copied().unwrap_or(0);
            }
            let full = (usize::from(qt.qt & 0x3F) << 12)
                | (usize::from(address >> 10 & 0x03) << 10)
                | usize::from(address & 0x3FF);
            return self.chr.get(full).copied().unwrap_or(0);
        }
        if !qt.sprite {
            return self
                .chr
                .get((usize::from(qt.qt & 1) << 12) | usize::from(address & 0x0FFF))
                .copied()
                .unwrap_or(0);
        }
        drop(qt);
        let bank = if address < 0x1000 {
            usize::from(self.reg[5] & 1)
        } else {
            1
        };
        let banks = (self.chr.len() / 0x1000).max(1);
        self.chr
            .get((bank % banks) * 0x1000 + usize::from(address & 0x0FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let bank = if address < 0x1000 {
            usize::from(self.reg[5] & 1)
        } else {
            1
        };
        let banks = (self.chr.len() / 0x1000).max(1);
        if let Some(byte) = self
            .chr
            .get_mut((bank % banks) * 0x1000 + usize::from(address & 0x0FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        if self.reg[10] & 2 != 0 {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        }
    }

    fn number(&self) -> u16 {
        547
    }

    fn qtram(&self) -> Option<Rc<RefCell<Qtram>>> {
        Some(Rc::clone(&self.qt))
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xD000..=0xDFFF).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if self.reg[9] & 2 == 0 {
            return;
        }
        self.irq_counter = self.irq_counter.wrapping_add(1);
        if self.irq_counter == 0 {
            self.irq_pending = true;
            self.irq_counter = u16::from(self.reg[6]) | (u16::from(self.reg[7]) << 8);
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

