/// OKI MSM6585 ADPCM decoder used by the Rinco FSG2 board.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
struct Msm6585 {
    which_nibble: bool,
    input: u8,
    signal: i32,
    count: i32,
    rate: i32,
    step: i32,
    low: f32,
    lower: f32,
}

impl Msm6585 {
    const HOST_CLOCK: i32 = 1_789_773;

    fn new() -> Self {
        Self {
            which_nibble: false,
            input: 0,
            signal: 0,
            count: 0,
            rate: 4000,
            step: 0,
            low: 0.0,
            lower: 0.0,
        }
    }

    fn set_rate(&mut self, value: u8) {
        // `$5001` bits 7-6 select 4/8/16/32 kHz.
        self.rate = 4000 << (value >> 6);
        self.count = 0;
    }

    /// Decodes one host clock; consumes a byte from the FIFO every two
    /// nibbles.
    fn clock(&mut self, fifo: &mut VecDeque<u8>) {
        self.count += self.rate;
        while self.count >= Self::HOST_CLOCK {
            self.count -= Self::HOST_CLOCK;
            let nibble = if self.which_nibble {
                self.input & 0x0F
            } else {
                self.input = fifo.pop_front().unwrap_or(0);
                self.input >> 4
            };
            self.which_nibble = !self.which_nibble;
            self.signal += i32::from(MSM6585_DIFF[self.step as usize * 16 + usize::from(nibble)]);
            self.signal = self.signal.clamp(-2048, 2047);
            self.step += i32::from(MSM6585_INDEX_SHIFT[usize::from(nibble & 0x07)]);
            self.step = self.step.clamp(0, 48);
        }
    }

    /// Two cascaded one-pole filters at 40% of the sample rate approximate the
    /// chip's reconstruction filter.
    fn output(&mut self) -> f32 {
        let cutoff = (self.rate as f32 * 0.4).clamp(200.0, 16_000.0);
        let alpha = 1.0 - (-std::f32::consts::TAU * cutoff / Self::HOST_CLOCK as f32).exp();
        self.low += alpha * (self.signal as f32 * 16.0 - self.low);
        self.lower += alpha * (self.low - self.lower);
        self.lower / 65_536.0
    }
}

/// Rinco FSG2 / Talkman (mapper 594): an MMC3 core with an outer 256 KiB
/// PRG/CHR bank, 8 KiB PRG-ROM at `$6000`, and an MSM6585 ADPCM FIFO at
/// `$5000`/`$5001`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mapper594 {
    inner: Mmc3,
    reg: [u8; 4],
    fifo: VecDeque<u8>,
    adpcm: Msm6585,
    output: f32,
    prg_ram: Vec<u8>,
}

impl Mapper594 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            inner: Mmc3::new_as(prg, chr, header, 594),
            reg: [0; 4],
            fifo: VecDeque::with_capacity(1024),
            adpcm: Msm6585::new(),
            output: 0.0,
            prg_ram,
        }
    }

    fn prg_or(&self) -> usize {
        (if self.reg[2] & 0x40 != 0 { 0xC0 } else { 0 })
            | (if self.reg[2] & 0x80 != 0 { 0x100 } else { 0 })
    }

    fn chr_and(&self) -> usize {
        if self.reg[2] & 0xC0 != 0 {
            0xFF
        } else {
            0x1FF
        }
    }

    fn chr_or(&self) -> usize {
        (if self.reg[2] & 0x40 != 0 { 0x200 } else { 0 })
            | (if self.reg[2] & 0x80 != 0 { 0x300 } else { 0 })
    }

    fn chr_bank(&self, slot: usize) -> usize {
        let inner = self.inner.chr_slot_bank(slot);
        let outer = inner | ((slot << 6) & 0x100);
        (outer & self.chr_and()) | self.chr_or()
    }
}

impl Mapper for Mapper594 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x5000..=0x5FFF => {
                if self.fifo.len() >= 512 {
                    0x00
                } else {
                    0x40
                }
            }
            0x6000..=0x7FFF => {
                let banks = (self.inner.prg.len() / 0x2000).max(1);
                let bank = (usize::from(self.reg[0]) | self.prg_or()) % banks;
                self.inner
                    .prg
                    .get(bank * 0x2000 + usize::from(address - 0x6000))
                    .copied()
                    .unwrap_or(0)
            }
            0x8000..=0xFFFF => {
                let slot = usize::from((address - 0x8000) / 0x2000);
                let banks = (self.inner.prg.len() / 0x2000).max(1);
                let bank = (self.inner.prg_slot_in(slot, 64) & 0x3F) | self.prg_or();
                self.inner
                    .prg
                    .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
                    .copied()
                    .unwrap_or(0)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x5000..=0x5FFF => {
                if address & 1 != 0 {
                    self.adpcm.set_rate(value);
                    self.fifo.clear();
                } else {
                    if self.fifo.len() >= 1024 {
                        self.fifo.pop_front();
                    }
                    self.fifo.push_back(value);
                }
            }
            0x9000..=0x9FFF => self.reg[usize::from(address & 1)] = value,
            0xB000..=0xBFFF => self.reg[2 + usize::from(address & 1)] = value,
            0x8000..=0xFFFF => self.inner.prg_write(address, value),
            _ => {}
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        self.prg_read(address)
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x5000, 0x5FFF))
    }

    fn prg_rom_at_6000(&self) -> bool {
        true
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let bank = self.chr_bank(slot) % banks;
        self.inner
            .chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let bank = self.chr_bank(slot) % banks;
        if let Some(byte) = self
            .inner
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        594
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xB000..=0xBFFF).contains(&address) || self.inner.chr_mapping_write(address)
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }

    fn clock_cpu(&mut self) {
        self.adpcm.clock(&mut self.fifo);
        self.output = self.adpcm.output();
    }

    fn audio_mix(&self) -> f32 {
        self.output
    }
}

/// Shared 16 KiB CHR-RAM for CPROM (mapper 13): PPU $0000-$0FFF is fixed
/// to the first 4 KiB, $1000-$1FFF selects one of four 4 KiB banks.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct CpromChr {
    ram: Vec<u8>,
    bank: u8,
}

impl CpromChr {
    fn new() -> Self {
        Self {
            ram: vec![0; 0x4000],
            bank: 0,
        }
    }

    fn set_bank(&mut self, bank: u8) {
        self.bank = bank & 0x03;
    }

    fn offset(&self, address: u16) -> usize {
        let index = usize::from(address & 0x1FFF);
        if index < 0x1000 {
            index
        } else {
            usize::from(self.bank) * 0x1000 + (index - 0x1000)
        }
    }

    pub(crate) fn read(&self, address: u16) -> u8 {
        self.ram.get(self.offset(address)).copied().unwrap_or(0)
    }

    pub(crate) fn write(&mut self, address: u16, value: u8) {
        let offset = self.offset(address);
        if let Some(byte) = self.ram.get_mut(offset) {
            *byte = value;
        }
    }
}

/// Shared CHR-RAM state for mapper 169's Yuxing computer modes: an 8 KiB
/// page selected by `$5501`, plus the 1-bpp all-points-addressable mode and
/// the nametable-in-CHR split mode selected by `$4800`/`$5500`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Chr169 {
    ram: Vec<u8>,
    page: u8,
    one_bpp: bool,
    nt_split: bool,
    pa00: bool,
    pa09: bool,
    pa13: bool,
}

impl Chr169 {
    fn new() -> Self {
        Self {
            ram: vec![0; 0x40000],
            page: 0,
            one_bpp: false,
            nt_split: false,
            pa00: false,
            pa09: false,
            pa13: false,
        }
    }

    fn configure(&mut self, page: u8, one_bpp: bool, nt_split: bool) {
        self.page = page & 0x1F;
        self.one_bpp = one_bpp;
        self.nt_split = nt_split;
    }

    /// Latches PPU A0/A9 on the rising edge of A13, as the board does.
    pub(crate) fn note_address(&mut self, address: u16) {
        let a13 = address & 0x2000 != 0;
        if !self.pa13 && a13 {
            self.pa00 = address & 0x0001 != 0;
            self.pa09 = address & 0x0200 != 0;
        }
        self.pa13 = a13;
    }

    fn base(&self) -> usize {
        usize::from(self.page) * 0x2000
    }

    pub(crate) fn read(&mut self, address: u16) -> u8 {
        self.note_address(address);
        let mut offset = usize::from(address & 0x1FFF);
        if self.one_bpp {
            offset = (offset & !8) | if self.pa00 { 8 } else { 0 };
        }
        let len = self.ram.len().max(1);
        self.ram
            .get((self.base() + offset) % len)
            .copied()
            .unwrap_or(0)
    }

    pub(crate) fn write(&mut self, address: u16, value: u8) {
        self.note_address(address);
        let len = self.ram.len().max(1);
        let index = (self.base() + usize::from(address & 0x1FFF)) % len;
        if let Some(byte) = self.ram.get_mut(index) {
            *byte = value;
        }
    }

    pub(crate) fn nt_split(&self) -> bool {
        self.nt_split
    }

    pub(crate) fn nt_read(&mut self, address: u16) -> u8 {
        self.note_address(0x2000 | (address & 0x0FFF));
        let len = self.ram.len().max(1);
        self.ram
            .get((self.base() + usize::from(address & 0x0FFF)) % len)
            .copied()
            .unwrap_or(0)
    }

    pub(crate) fn nt_write(&mut self, address: u16, value: u8) {
        let len = self.ram.len().max(1);
        let index = (self.base() + usize::from(address & 0x0FFF)) % len;
        if let Some(byte) = self.ram.get_mut(index) {
            *byte = value;
        }
    }
}

/// Yuxing educational computer (mapper 169): MMC3-register game mode when
/// `$5501.7` is set, otherwise a computer mode with `$4800` selecting a
/// 32 KiB PRG-ROM bank (or PRG-RAM windows) and `$4800`/`$5500`/`$5501`
/// selecting the CHR-RAM paging and 1-bpp/NT-split graphics modes.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mapper169 {
    mmc3: Mmc3,
    prg_ram: Vec<u8>,
    reg4800: u8,
    reg5500: u8,
    reg5501: u8,
    ram_latch: u8,
    keyboard_row: u16,
    chr: Rc<RefCell<Chr169>>,
}

impl Mapper169 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            mmc3: Mmc3::new_as(prg, chr, header, 169),
            prg_ram: vec![0; 0x80000],
            reg4800: 0,
            reg5500: 0,
            reg5501: 0,
            ram_latch: 0,
            keyboard_row: 0,
            chr: Rc::new(RefCell::new(Chr169::new())),
        }
    }

    fn sync_chr(&self) {
        let r = self.reg5501;
        let page = (r & 0x10) | ((r << 2) & 0x0C) | ((r >> 2) & 0x03);
        let special = self.reg4800 & 0x80 != 0;
        let nt_split = special && self.reg5500 & 0x80 != 0;
        self.chr
            .borrow_mut()
            .configure(page, special && !nt_split, nt_split);
    }

    fn ram_8k_bank(&self) -> usize {
        if self.reg5500 & 0x03 == 0 {
            0x3C
        } else {
            usize::from(self.reg5500 & 0x03)
        }
    }

    /// Byte offset of a `$8000-$FFFF` access in the mapped RAM windows.
    fn ram_offset(&self, address: u16) -> usize {
        if self.reg5500 & 0x40 != 0 {
            (usize::from(self.ram_latch) >> 1) * 0x8000 + usize::from(address - 0x8000)
        } else if address < 0xC000 {
            usize::from(self.ram_latch) * 0x4000 + usize::from(address - 0x8000)
        } else {
            0x3C000 + usize::from(address - 0xC000)
        }
    }

    fn ram_byte(&self, offset: usize) -> u8 {
        let len = self.prg_ram.len().max(1);
        self.prg_ram.get(offset % len).copied().unwrap_or(0)
    }
}

impl Mapper for Mapper169 {
    fn prg_read(&self, address: u16) -> u8 {
        if self.reg5501 & 0x80 != 0 {
            return self.mmc3.prg_read(address);
        }
        match address {
            0x6000..=0x7FFF => {
                let bank = self.ram_8k_bank();
                self.ram_byte(bank * 0x2000 + usize::from(address - 0x6000))
            }
            0x8000..=0xFFFF => {
                if self.reg5500 & 0x04 != 0 {
                    self.ram_byte(self.ram_offset(address))
                } else {
                    let bank = usize::from(self.reg4800 & 0x1F);
                    let len = self.mmc3.prg.len().max(1);
                    self.mmc3
                        .prg
                        .get((bank * 0x8000 + usize::from(address - 0x8000)) % len)
                        .copied()
                        .unwrap_or(0)
                }
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x4200 => {}
            0x4201 => {}
            0x4202 | 0x4302 | 0x5004 => {
                self.keyboard_row = (self.keyboard_row & 0xFF00) | u16::from(value);
            }
            0x4203 | 0x4303 | 0x5005 => {
                self.keyboard_row = (self.keyboard_row & 0x00FF) | (u16::from(value) << 8);
            }
            0x4205 => {}
            0x4800 => {
                self.reg4800 = value;
                self.sync_chr();
            }
            0x5500 => {
                self.reg5500 = value;
                self.sync_chr();
            }
            0x5501 => {
                self.reg5501 = value;
                self.sync_chr();
            }
            0x8000..=0xFFFF => {
                if self.reg5501 & 0x80 != 0 {
                    self.mmc3.prg_write(address, value);
                    return;
                }
                if self.reg5500 & 0x04 != 0 {
                    if self.reg4800 & 0x20 != 0 {
                        self.ram_latch = value;
                    } else {
                        let len = self.prg_ram.len().max(1);
                        let index = self.ram_offset(address) % len;
                        self.prg_ram[index] = value;
                    }
                }
            }
            _ => {}
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        match address {
            0x4207 => {
                // No keyboard is attached: every row reads back released.
                let _ = self.keyboard_row;
                0
            }
            0x4204 | 0x4205 | 0x4304 | 0x4305 => 0x80,
            0x5002 => 0x02,
            0x8000..=0xFFFF => self.prg_read(address),
            _ => 0,
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x4200, 0x5FFF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        if self.reg5501 & 0x80 != 0 {
            return self.mmc3.chr_read(address);
        }
        self.chr.borrow_mut().read(address)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if self.reg5501 & 0x80 != 0 {
            self.mmc3.chr_write(address, value);
            return;
        }
        self.chr.borrow_mut().write(address, value);
    }

    fn mirroring(&self) -> Mirroring {
        if self.reg5501 & 0x80 != 0 {
            self.mmc3.mirroring()
        } else if self.reg5500 & 0x08 != 0 {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        }
    }

    fn number(&self) -> u16 {
        169
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        matches!(address, 0x4800 | 0x5500 | 0x5501)
    }

    fn chr169(&self) -> Option<Rc<RefCell<Chr169>>> {
        Some(self.chr.clone())
    }

    fn irq_line(&self) -> bool {
        if self.reg5501 & 0x80 != 0 {
            self.mmc3.irq_line()
        } else {
            false
        }
    }

    fn clock_scanline(&mut self) {
        if self.reg5501 & 0x80 != 0 {
            self.mmc3.clock_scanline();
        }
    }

    fn acknowledge_irq(&mut self) {
        if self.reg5501 & 0x80 != 0 {
            self.mmc3.acknowledge_irq();
        }
    }
}

/// Minimal PIC16C54 interpreter for mapper 355's protection MCU.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Pic16c54 {
    rom: Vec<u16>,
    ram: [u8; 32],
    w: u8,
    pc: u16,
    stack: [u16; 2],
    sp: u8,
    tris_a: u8,
    tris_b: u8,
    option: u8,
    clock2cycle: u8,
    icount: i32,
    inst_cycles: i32,
    delay_timer: i32,
    prescaler: u32,
    /// Current CPU bus address, presented on the port pins.
    pub cpu_address: u16,
    /// Level of the MCU's /IRQ output.
    pub irq: bool,
}

impl Pic16c54 {
    fn new(misc: &[u8]) -> Self {
        let mut rom = vec![0u16; 512];
        for (index, word) in rom.iter_mut().enumerate() {
            let low = misc.get(index * 2).copied().unwrap_or(0);
            let high = misc.get(index * 2 + 1).copied().unwrap_or(0);
            *word = u16::from(low) | (u16::from(high) << 8);
        }
        let mut this = Self {
            rom,
            ram: [0; 32],
            w: 0,
            pc: 0x1FF,
            stack: [0; 2],
            sp: 0,
            tris_a: 0xFF,
            tris_b: 0xFF,
            option: 0x3F,
            clock2cycle: 0,
            icount: 0,
            inst_cycles: 1,
            delay_timer: 0,
            prescaler: 0,
            cpu_address: 0,
            irq: false,
        };
        this.reset();
        this
    }

    fn reset(&mut self) {
        self.ram = [0; 32];
        self.w = 0;
        self.pc = 0x1FF;
        self.stack = [0; 2];
        self.sp = 0;
        self.tris_a = 0xFF;
        self.tris_b = 0xFF;
        self.option = 0x3F;
        self.clock2cycle = 0;
        self.icount = 0;
        self.inst_cycles = 1;
        self.delay_timer = 0;
        self.prescaler = 0;
        self.irq = false;
        self.ram[2] = 0xFF;
        self.ram[3] = 0x18;
        self.ram[4] = 0xE0;
    }

    fn status(&self) -> u8 {
        self.ram[3]
    }

    fn carries(&self) -> bool {
        self.ram[3] & 0x01 != 0
    }

    fn set_carry(&mut self, value: bool) {
        if value {
            self.ram[3] |= 0x01;
        } else {
            self.ram[3] &= !0x01;
        }
    }

    fn set_dc(&mut self, value: bool) {
        if value {
            self.ram[3] |= 0x02;
        } else {
            self.ram[3] &= !0x02;
        }
    }

    fn set_zero(&mut self, value: bool) {
        if value {
            self.ram[3] |= 0x04;
        } else {
            self.ram[3] &= !0x04;
        }
    }

    fn port_a_in(&self) -> u8 {
        let a = self.cpu_address;
        let mut value = 1u8;
        if a & 0x0040 != 0 {
            value |= 0x02;
        }
        if a & 0x0020 != 0 {
            value |= 0x04;
        }
        if a & 0x0010 != 0 {
            value |= 0x08;
        }
        value
    }

    fn port_b_in(&self) -> u8 {
        let a = self.cpu_address;
        let bits = [
            (0x1000u16, 0x01u8),
            (0x0080, 0x02),
            (0x0400, 0x04),
            (0x0800, 0x08),
            (0x0200, 0x10),
            (0x0100, 0x20),
            (0x2000, 0x40),
            (0x4000, 0x80),
        ];
        let mut value = 0u8;
        for (mask, bit) in bits {
            if a & mask != 0 {
                value |= bit;
            }
        }
        value
    }

    /// Applies a port-A output; bit 12 marks a TRIS update.
    fn port_a_out(&mut self, value: u16) {
        self.irq = value & 0x1001 != 0;
    }

    fn get_reg(&mut self, address: u8) -> u8 {
        let index = if address == 0 {
            usize::from(self.ram[4] & 0x1F)
        } else {
            usize::from(address & 0x1F)
        };
        match index {
            0 => 0,
            4 => self.ram[4] | 0xE0,
            5 => (self.port_a_in() & self.tris_a) | ((!self.tris_a) & self.ram[5]) & 0x0F,
            6 => (self.port_b_in() & self.tris_b) | ((!self.tris_b) & self.ram[6]),
            _ => self.ram[index],
        }
    }

    fn set_reg(&mut self, address: u8, value: u8) {
        let index = if address == 0 {
            usize::from(self.ram[4] & 0x1F)
        } else {
            usize::from(address & 0x1F)
        };
        match index {
            0 => {}
            1 => {
                self.delay_timer = 2;
                if self.option & 0x08 == 0 {
                    self.prescaler = 0;
                }
                self.ram[1] = value;
            }
            2 => {
                self.ram[2] = value;
                self.pc = (((u16::from(self.ram[3]) & 0xE0) << 4) | u16::from(value)) & 0x1FF;
            }
            3 => {
                self.ram[3] = (self.ram[3] & 0x18) | (value & !0x18);
            }
            4 => {
                self.ram[4] = value | 0xE0;
            }
            5 => {
                let value = value & 0x0F;
                let out = u16::from(value & !self.tris_a);
                self.port_a_out(out);
                self.ram[5] = value;
            }
            6 => {
                self.ram[6] = value;
            }
            _ => self.ram[index] = value,
        }
    }

    fn store_result(&mut self, address: u8, value: u8, to_reg: bool) {
        if to_reg {
            self.set_reg(address, value);
        } else {
            self.w = value;
        }
    }

    fn skip(&mut self) {
        self.pc = (self.pc.wrapping_add(1)) & 0x1FF;
        self.ram[2] = self.ram[2].wrapping_add(1);
        self.inst_cycles += 1;
    }

    fn push(&mut self) {
        let slot = usize::from(self.sp & 1);
        self.stack[slot] = self.pc;
        self.sp = self.sp.wrapping_add(1);
    }

    fn pop(&mut self) -> u16 {
        self.sp = self.sp.wrapping_sub(1);
        self.stack[usize::from(self.sp & 1)]
    }

    fn update_timer(&mut self, counts: u32) {
        if self.option & 0x08 == 0 {
            self.prescaler += counts;
            let limit = 2u32 << (self.option & 0x07);
            if self.prescaler >= limit {
                self.ram[1] = self.ram[1].wrapping_add((self.prescaler / limit) as u8);
                self.prescaler %= limit;
            }
        } else {
            self.ram[1] = self.ram[1].wrapping_add(counts as u8);
        }
    }

    fn execute(&mut self, op: u16) {
        self.inst_cycles = 1;
        let file = (op & 0x1F) as u8;
        let to_reg = op & 0x20 != 0;
        if op & 0xFF0 != 0 {
            match (op >> 4) & 0xFF {
                0x02 | 0x03 => {
                    let value = self.w;
                    self.set_reg(file, value);
                }
                0x04 => {
                    self.w = 0;
                    self.set_zero(true);
                }
                0x06 | 0x07 => {
                    self.set_reg(file, 0);
                    self.set_zero(true);
                }
                0x08..=0x0B => {
                    let old = self.get_reg(file);
                    let alu = old.wrapping_sub(self.w);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                    self.set_carry(old >= alu);
                    self.set_dc((old & 0x0F) >= (alu & 0x0F));
                }
                0x0C..=0x0F => {
                    let alu = self.get_reg(file).wrapping_sub(1);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x10..=0x13 => {
                    let alu = self.get_reg(file) | self.w;
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x14..=0x17 => {
                    let alu = self.get_reg(file) & self.w;
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x18..=0x1B => {
                    let alu = self.get_reg(file) ^ self.w;
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x1C..=0x1F => {
                    let old = self.get_reg(file);
                    let alu = old.wrapping_add(self.w);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                    self.set_carry(old > alu);
                    self.set_dc((old & 0x0F) > (alu & 0x0F));
                }
                0x20..=0x23 => {
                    let alu = self.get_reg(file);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x24..=0x27 => {
                    let alu = !self.get_reg(file);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x28..=0x2B => {
                    let alu = self.get_reg(file).wrapping_add(1);
                    self.store_result(file, alu, to_reg);
                    self.set_zero(alu == 0);
                }
                0x2C..=0x2F => {
                    let alu = self.get_reg(file).wrapping_sub(1);
                    self.store_result(file, alu, to_reg);
                    if alu == 0 {
                        self.skip();
                    }
                }
                0x30..=0x33 => {
                    let mut alu = self.get_reg(file);
                    let bit7 = alu & 0x80 != 0;
                    alu = (alu << 1) | u8::from(self.carries());
                    self.store_result(file, alu, to_reg);
                    self.set_carry(bit7);
                }
                0x34..=0x37 => {
                    let mut alu = self.get_reg(file);
                    let bit0 = alu & 0x01 != 0;
                    alu = (alu >> 1) | if self.carries() { 0x80 } else { 0 };
                    self.store_result(file, alu, to_reg);
                    self.set_carry(bit0);
                }
                0x38..=0x3B => {
                    let value = self.get_reg(file);
                    let alu = value.rotate_right(4);
                    self.store_result(file, alu, to_reg);
                }
                0x3C..=0x3F => {
                    let alu = self.get_reg(file).wrapping_add(1);
                    self.store_result(file, alu, to_reg);
                    if alu == 0 {
                        self.skip();
                    }
                }
                0x40..=0x4F => {
                    let bit = 1u8 << ((op >> 5) & 0x07);
                    let value = self.get_reg(file) & !bit;
                    self.set_reg(file, value);
                }
                0x50..=0x5F => {
                    let bit = 1u8 << ((op >> 5) & 0x07);
                    let value = self.get_reg(file) | bit;
                    self.set_reg(file, value);
                }
                0x60..=0x6F => {
                    let bit = 1u8 << ((op >> 5) & 0x07);
                    if self.get_reg(file) & bit == 0 {
                        self.skip();
                    }
                }
                0x70..=0x7F => {
                    let bit = 1u8 << ((op >> 5) & 0x07);
                    if self.get_reg(file) & bit != 0 {
                        self.skip();
                    }
                }
                0x80..=0x8F => {
                    self.w = (op & 0xFF) as u8;
                    self.pc = self.pop() & 0x1FF;
                    self.ram[2] = self.pc as u8;
                    self.inst_cycles = 2;
                }
                0x90..=0x9F => {
                    self.push();
                    let page = (u16::from(self.status()) & 0xE0) << 4;
                    self.pc = (page | (op & 0xFF)) & 0x1FF;
                    self.ram[2] = self.pc as u8;
                    self.inst_cycles = 2;
                }
                0xA0..=0xBF => {
                    let page = (u16::from(self.status()) & 0xE0) << 4;
                    self.pc = (page | (op & 0x1FF)) & 0x1FF;
                    self.ram[2] = self.pc as u8;
                    self.inst_cycles = 2;
                }
                0xC0..=0xCF => self.w = (op & 0xFF) as u8,
                0xD0..=0xDF => {
                    self.w |= (op & 0xFF) as u8;
                    self.set_zero(self.w == 0);
                }
                0xE0..=0xEF => {
                    self.w &= (op & 0xFF) as u8;
                    self.set_zero(self.w == 0);
                }
                0xF0..=0xFF => {
                    self.w ^= (op & 0xFF) as u8;
                    self.set_zero(self.w == 0);
                }
                _ => {}
            }
        } else {
            match op & 0x1F {
                0x00 => {}
                0x02 => self.option = self.w & 0x3F,
                0x03 => {
                    self.ram[3] |= 0x10;
                    self.ram[3] &= !0x08;
                }
                0x04 => {
                    self.ram[3] |= 0x18;
                }
                0x05 => {
                    self.tris_a = self.w;
                    let value = 0x1000 | u16::from(self.ram[5] & !self.tris_a & 0x0F);
                    self.port_a_out(value);
                }
                0x06 => self.tris_b = self.w,
                _ => {}
            }
        }
    }

    /// Advances the MCU by one M2 cycle (four cycles per instruction).
    pub fn run(&mut self) {
        self.clock2cycle = self.clock2cycle.wrapping_add(1);
        if self.clock2cycle & 3 == 0 {
            self.icount += 1;
        }
        while self.icount > 0 {
            if self.ram[3] & 0x08 == 0 {
                self.inst_cycles = 1;
            } else {
                let op = self.rom[usize::from(self.pc & 0x1FF)];
                self.pc = (self.pc.wrapping_add(1)) & 0x1FF;
                self.ram[2] = self.ram[2].wrapping_add(1);
                self.execute(op);
                if self.option & 0x20 == 0 {
                    if self.delay_timer > 0 {
                        self.delay_timer -= 1;
                    } else {
                        let counts = self.inst_cycles.max(1) as u32;
                        self.update_timer(counts);
                    }
                }
            }
            self.icount -= self.inst_cycles;
        }
    }
}

/// 3D-BLOCK / Block Force board (mapper 355): NROM-256 plus a PIC16C54
/// protection MCU that watches CPU A4-A14 and drives the cartridge IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mapper355 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    pic: Pic16c54,
    mirroring: Mirroring,
}

impl Mapper355 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, misc: &[u8], header: Header) -> Self {
        Self {
            prg,
            chr,
            pic: Pic16c54::new(misc),
            mirroring: header.mirroring,
        }
    }
}

impl Mapper for Mapper355 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x8000).max(1);
        self.prg
            .get(
                ((usize::from(address - 0x8000) / 0x8000) % banks) * 0x8000
                    + usize::from(address & 0x7FFF),
            )
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, _address: u16, _value: u8) {}

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        355
    }

    fn set_cpu_address(&mut self, address: u16) {
        self.pic.cpu_address = address;
    }

    fn clock_cpu(&mut self) {
        self.pic.run();
    }

    fn irq_line(&self) -> bool {
        self.pic.irq
    }

    fn acknowledge_irq(&mut self) {}
}

/// UM6578 enhanced famiclone (mapper 405): eight 4 KiB PRG windows selected
/// by readable `$4040-$4047` registers, 8 KiB work RAM plus 2 KiB at
/// `$5000`, the `$4031` enhanced-mode latch, the timer/IRQ registers and the
/// general-purpose `$4048-$404F` DMA engine.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Um6578 {
    prg: Vec<u8>,
    prg_ram: Vec<u8>,
    extra_ram: Vec<u8>,
    banks: [u8; 8],
    latch: u8,
    enhanced: bool,
    dma_ctrl: u8,
    dma_src_page: u8,
    dma_src_lsb: u8,
    dma_src_msb: u8,
    dma_dst_lsb: u8,
    dma_dst_msb: u8,
    dma_len_lsb: u8,
    dma_len_msb: u8,
    pending: bool,
    irq_mask: u8,
    irq_status: u8,
    mirroring: Mirroring,
    chr: Vec<u8>,
}

impl Um6578 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            prg_ram,
            extra_ram: vec![0; 0x800],
            banks: [0, 1, 2, 3, 4, 5, 6, 7],
            latch: 0,
            enhanced: false,
            dma_ctrl: 0,
            dma_src_page: 0,
            dma_src_lsb: 0,
            dma_src_msb: 0,
            dma_dst_lsb: 0,
            dma_dst_msb: 0,
            dma_len_lsb: 0,
            dma_len_msb: 0,
            pending: false,
            irq_mask: 0,
            irq_status: 0,
            mirroring: header.mirroring,
            chr,
        }
    }

    fn prg_window(&self, address: u16) -> usize {
        let slot = usize::from((address - 0x8000) / 0x1000);
        let banks = (self.prg.len() / 0x1000).max(1);
        let bank = usize::from(self.banks[slot]) % banks;
        bank * 0x1000 + usize::from(address & 0x0FFF)
    }
}

impl Mapper for Um6578 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x4033 => self.irq_status,
            0x4036 => 0,
            0x4040..=0x4047 => self.banks[usize::from(address - 0x4040)],
            0x4048 => self.dma_ctrl | if self.pending { 0x80 } else { 0 },
            0x4049 => self.dma_src_page,
            0x404A => self.dma_src_lsb,
            0x404B => self.dma_src_msb,
            0x404C => self.dma_dst_lsb,
            0x404D => self.dma_dst_msb,
            0x404E => self.dma_len_lsb,
            0x404F => self.dma_len_msb,
            0x5000..=0x57FF => self.extra_ram[usize::from(address - 0x5000)],
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)],
            0x8000..=0xFFFF => self.prg.get(self.prg_window(address)).copied().unwrap_or(0),
            _ => 0,
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        self.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x4031 => {
                self.enhanced = self.latch == 0x65 && value == 0x76;
                self.latch = value;
            }
            0x4032 => self.irq_mask = value,
            0x4040..=0x4047 => self.banks[usize::from(address - 0x4040)] = value,
            0x4048 => {
                self.dma_ctrl = value;
                if value & 0x80 != 0 {
                    self.pending = true;
                }
            }
            0x4049 => self.dma_src_page = value,
            0x404A => self.dma_src_lsb = value,
            0x404B => self.dma_src_msb = value,
            0x404C => self.dma_dst_lsb = value,
            0x404D => self.dma_dst_msb = value,
            0x404E => self.dma_len_lsb = value,
            0x404F => self.dma_len_msb = value,
            0x5000..=0x57FF => self.extra_ram[usize::from(address - 0x5000)] = value,
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)] = value,
            _ => {}
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x4032, 0x57FF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        405
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn um6578(&self) -> bool {
        true
    }

    fn take_dma(&mut self) -> Option<DmaRequest> {
        if !self.pending {
            return None;
        }
        self.pending = false;
        let source_rom = self.dma_src_msb & 0x80 != 0;
        let source = if source_rom {
            (u32::from(self.dma_src_page & 0x1F) << 15)
                | (u32::from(self.dma_src_msb & 0x7F) << 8)
                | u32::from(self.dma_src_lsb)
        } else {
            (u32::from(self.dma_src_msb & 0x7F) << 8) | u32::from(self.dma_src_lsb)
        };
        Some(DmaRequest {
            to_ppu: self.dma_ctrl & 0x20 == 0,
            source_rom,
            source,
            target: u16::from(self.dma_dst_lsb) | (u16::from(self.dma_dst_msb) << 8),
            len: (u16::from(self.dma_len_msb & 0x7F) << 8) | u16::from(self.dma_len_lsb),
        })
    }

    fn prg_linear(&self, offset: usize) -> u8 {
        self.prg.get(offset).copied().unwrap_or(0)
    }
}

/// Subor Sango II board (mapper 559): a VRC4 core whose register select
/// lines are CPU A10/A11, with a switchable `$C000` bank, per-quadrant
/// CHR-ROM nametables and a 9-bit CHR bank.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct SuborSango559 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    prg_regs: [u8; 2],
    chr_regs: [u16; 8],
    prg_flip: bool,
    wram_enable: bool,
    mirroring: Mirroring,
    cpu_c: u8,
    nt: [u16; 4],
    irq_latch: u8,
    irq_counter: u8,
    irq_reload: bool,
    irq_enabled: bool,
    irq_pending: bool,
}

impl SuborSango559 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            prg_regs: [0, 1],
            chr_regs: [0, 1, 2, 3, 4, 5, 6, 7],
            prg_flip: false,
            wram_enable: false,
            mirroring: header.mirroring,
            cpu_c: 0xFE,
            nt: [0xE0, 0xE0, 0xE1, 0xE1],
            irq_latch: 0,
            irq_counter: 0,
            irq_reload: false,
            irq_enabled: false,
            irq_pending: false,
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for SuborSango559 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)],
            0x8000..=0x9FFF => {
                let bank = if self.prg_flip {
                    0x1E
                } else {
                    usize::from(self.prg_regs[0] & 0x1F)
                };
                self.prg_8k(bank, address)
            }
            0xA000..=0xBFFF => self.prg_8k(usize::from(self.prg_regs[1] & 0x1F), address),
            0xC000..=0xDFFF => self.prg_8k(usize::from(self.cpu_c), address),
            0xE000..=0xFFFF => self.prg_8k(0x1F, address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x8000..=0x8FFF => self.prg_regs[0] = value,
            0xA000..=0xAFFF => self.prg_regs[1] = value,
            0x9000..=0x9FFF => match (address >> 10) & 0x03 {
                0 | 1 => {
                    self.mirroring = match value & 0x03 {
                        0 => Mirroring::Vertical,
                        1 => Mirroring::Horizontal,
                        2 => Mirroring::SingleLower,
                        _ => Mirroring::SingleUpper,
                    };
                }
                2 => {
                    self.wram_enable = value & 0x01 != 0;
                    self.prg_flip = value & 0x02 != 0;
                }
                _ => {
                    if address & 0x04 != 0 {
                        self.nt[usize::from(address & 0x03)] = u16::from(value);
                    } else {
                        self.cpu_c = value;
                    }
                }
            },
            0xB000..=0xEFFF => {
                let bank = (address >> 12) & 0x0F;
                let reg = usize::from((((bank - 0x0B) << 1) | ((address >> 11) & 1)) & 0x07);
                if address & 0x0400 != 0 {
                    self.chr_regs[reg] =
                        (self.chr_regs[reg] & 0x00F) | (u16::from(value & 0x0F) << 4);
                } else {
                    self.chr_regs[reg] = (self.chr_regs[reg] & 0xFF0) | u16::from(value & 0x0F);
                }
            }
            0xF000..=0xFFFF => {
                let val = if address & 0x0400 != 0 {
                    value >> 4
                } else {
                    value
                };
                match (address >> 10) & 0x03 {
                    0 => self.irq_latch = (self.irq_latch & 0xF0) | (val & 0x0F),
                    1 => self.irq_latch = (self.irq_latch & 0x0F) | ((val & 0x0F) << 4),
                    2 => {
                        self.irq_enabled = val & 0x02 != 0;
                        if self.irq_enabled {
                            self.irq_counter = self.irq_latch;
                            self.irq_reload = true;
                        }
                        self.irq_pending = false;
                    }
                    _ => self.irq_pending = false,
                }
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_regs[slot] & 0x01FF) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_regs[slot] & 0x01FF) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        559
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xB000..=0xEFFF).contains(&address)
    }

    fn has_rom_nametables(&self) -> bool {
        true
    }

    fn chr_rom(&self) -> Option<&[u8]> {
        if self.chr.is_empty() {
            None
        } else {
            Some(&self.chr)
        }
    }

    fn rom_nametable_quadrants(&self) -> Option<[u16; 4]> {
        Some(self.nt)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if self.irq_counter == 0 || self.irq_reload {
            self.irq_counter = self.irq_latch;
            self.irq_reload = false;
        } else {
            self.irq_counter -= 1;
            if self.irq_counter == 0 && self.irq_enabled {
                self.irq_pending = true;
            }
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// J-2020 board (mapper 563): a VRC2 core with the $F000 register bank
/// repurposed as an A12-edge IRQ control.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct J2020_563 {
    inner: Vrc,
    a12: Rc<RefCell<A12Irq>>,
}

impl J2020_563 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, prg_ram: Vec<u8>, header: Header) -> Self {
        let mut vrc_header = header;
        // VRC2b register wiring (A0/A1 at address bits 0/1).
        vrc_header.mapper = 23;
        // Our mapper-23 table maps submapper 3 to the VRC2b A0/A1 decode.
        vrc_header.submapper = 3;
        Self {
            inner: Vrc::new(prg, chr, prg_ram, vrc_header),
            a12: Rc::new(RefCell::new(A12Irq::new())),
        }
    }
}

impl Mapper for J2020_563 {
    fn prg_read(&self, address: u16) -> u8 {
        self.inner.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0xF000 {
            let mut irq = self.a12.borrow_mut();
            irq.pending = false;
            match address & 0x1C {
                0x0C => irq.enabled = false,
                0x08 => irq.enabled = true,
                0x1C => irq.counter = 0,
                _ => {}
            }
            return;
        }
        self.inner.prg_write(address, value);
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.inner.chr_read(address)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        self.inner.chr_write(address, value);
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        563
    }

    fn prg_ram(&self) -> &[u8] {
        self.inner.prg_ram()
    }

    fn a12_irq(&self) -> Option<Rc<RefCell<A12Irq>>> {
        Some(self.a12.clone())
    }

    fn irq_line(&self) -> bool {
        self.a12.borrow().pending
    }

    fn acknowledge_irq(&mut self) {
        self.a12.borrow_mut().pending = false;
    }
}

/// Nintendo Campus Challenge 1991 / NES-EVENT2 (mapper 555): an MMC3 core
/// with extended PRG/CHR banking from a `$5800` register, a TQROM CHR-RAM
/// mode and a cycle timer reported through the `$5800` status read.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct NeSEvent2_555 {
    inner: Mmc3,
    prg_ram: Vec<u8>,
    chr_ram: Vec<u8>,
    reg: [u8; 2],
    counter: u32,
    expired: bool,
}

impl NeSEvent2_555 {
    /// Timer target with all DIP switches off (~5 minutes at 1.79 MHz).
    const TIMER_TARGET: u32 = 0x2000_0000;

    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2800, 0);
        Self {
            inner: Mmc3::new_as(prg, chr, header, 555),
            prg_ram,
            chr_ram: vec![0; 0x2_2000],
            reg: [0; 2],
            counter: 0,
            expired: false,
        }
    }

    fn prg_and(&self) -> u8 {
        0x07 | ((self.reg[0] << 3) & 0x18)
    }

    fn prg_or(&self) -> u8 {
        (self.reg[0] << 3) & 0x20
    }

    fn chr_or(&self) -> u8 {
        (self.reg[0] << 5) & 0x80
    }

    fn tqrom(&self) -> bool {
        self.reg[0] & 0x06 == 0x02
    }

    fn chr_slot_page(&self, slot: usize) -> (bool, usize) {
        let raw = self.inner.chr_bank_in(slot, 256) as u8;
        if self.tqrom() && raw & 0x40 != 0 {
            let page = usize::from((raw & 0x07) | self.chr_or());
            (true, page)
        } else {
            let banks = (self.inner.chr.len() / 0x400).max(1);
            let bank = (usize::from(raw & 0x7F) | usize::from(self.chr_or())) % banks;
            (false, bank)
        }
    }
}

impl Mapper for NeSEvent2_555 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x5000..=0x57FF => self.prg_ram[0x2000 + usize::from(address - 0x5000)],
            0x5800..=0x5FFF => 0x5C | if self.expired { 0x80 } else { 0 },
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)],
            0x8000..=0xFFFF => {
                let slot = usize::from((address - 0x8000) / 0x2000);
                let bank =
                    (self.inner.prg_slot_in(slot, 256) as u8 & self.prg_and()) | self.prg_or();
                let banks = (self.inner.prg.len() / 0x2000).max(1);
                self.inner
                    .prg
                    .get((usize::from(bank) % banks) * 0x2000 + usize::from(address & 0x1FFF))
                    .copied()
                    .unwrap_or(0)
            }
            _ => 0,
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        if (0x5000..=0x5FFF).contains(&address) {
            return self.prg_read(address);
        }
        self.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x5000..=0x57FF => {
                self.prg_ram[0x2000 + usize::from(address - 0x5000)] = value;
            }
            0x5800..=0x5BFF => self.reg[0] = value,
            0x5C00..=0x5FFF => self.reg[1] = value,
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)] = value,
            _ if address >= 0x8000 => self.inner.prg_write(address, value),
            _ => {}
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x5000, 0x5FFF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let (ram, page) = self.chr_slot_page(slot);
        let offset = page * 0x400 + usize::from(address & 0x3FF);
        if ram {
            self.chr_ram.get(offset).copied().unwrap_or(0)
        } else {
            self.inner.chr.get(offset).copied().unwrap_or(0)
        }
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let (ram, page) = self.chr_slot_page(slot);
        let offset = page * 0x400 + usize::from(address & 0x3FF);
        if ram {
            if let Some(byte) = self.chr_ram.get_mut(offset) {
                *byte = value;
            }
        } else if let Some(byte) = self.inner.chr.get_mut(offset) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        555
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x5800..=0x5BFF).contains(&address) || self.inner.chr_mapping_write(address)
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }

    fn clock_cpu(&mut self) {
        if self.reg[0] & 0x08 != 0 {
            self.counter = 0;
            self.expired = false;
        } else if self.counter != Self::TIMER_TARGET {
            self.counter = self.counter.wrapping_add(1);
            if self.counter == Self::TIMER_TARGET {
                self.expired = true;
            }
        }
    }
}

/// Sangokushi II bootleg (mapper 330): three 8 KiB PRG windows with the last
/// bank fixed, eight 1 KiB CHR registers, four nametable registers, the
/// Namco 163 chip RAM at `$4800` and its 15-bit CPU-cycle IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Sangokushi330 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    prg_banks: [u8; 3],
    chr_banks: [u8; 8],
    nt: [u8; 4],
    #[serde(with = "serde_big_array::BigArray")]
    chip_ram: [u8; 128],
    chip_addr: u8,
    chip_inc: bool,
    irq_counter: u16,
    irq_pending: bool,
}

impl Sangokushi330 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, _header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        let mut chr_banks = [0u8; 8];
        for (i, bank) in chr_banks.iter_mut().enumerate() {
            *bank = i as u8;
        }
        Self {
            prg,
            chr,
            prg_ram,
            prg_banks: [0, 1, 2],
            chr_banks,
            nt: [0, 1, 0, 1],
            chip_ram: [0; 128],
            chip_addr: 0,
            chip_inc: false,
            irq_counter: 0,
            irq_pending: false,
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Sangokushi330 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x4800..=0x4FFF => self.chip_ram[usize::from(self.chip_addr) & 0x7F],
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000) % self.prg_ram.len()],
            0x8000..=0x9FFF => self.prg_8k(usize::from(self.prg_banks[0]), address),
            0xA000..=0xBFFF => self.prg_8k(usize::from(self.prg_banks[1]), address),
            0xC000..=0xDFFF => self.prg_8k(usize::from(self.prg_banks[2]), address),
            0xE000..=0xFFFF => self.prg_8k(0xFF, address),
            _ => 0,
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        if (0x4800..=0x4FFF).contains(&address) {
            return self.chip_ram[usize::from(self.chip_addr) & 0x7F];
        }
        self.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x4800..=0x4FFF => {
                let index = usize::from(self.chip_addr) & 0x7F;
                self.chip_ram[index] = value;
                if self.chip_inc && index < 0x7F {
                    self.chip_addr = (index + 1) as u8;
                }
            }
            0x6000..=0x7FFF => {
                let index = usize::from(address - 0x6000) % self.prg_ram.len();
                self.prg_ram[index] = value;
            }
            0x8000..=0xBFFF => {
                let bank = (address >> 12) & 0x0F;
                if address & 0x0400 != 0 {
                    if bank & 0x02 != 0 {
                        self.irq_counter = (self.irq_counter & 0x00FF) | (u16::from(value) << 8);
                        self.irq_pending = false;
                    } else {
                        self.irq_counter = (self.irq_counter & 0xFF00) | u16::from(value);
                    }
                } else {
                    let index = usize::from(((bank & 0x03) << 1) | ((address >> 11) & 1)) & 0x07;
                    self.chr_banks[index] = value;
                }
            }
            0xC000..=0xDFFF => {
                if address & 0x0400 == 0 {
                    let index =
                        usize::from((((address >> 12) & 1) << 1) | ((address >> 11) & 1)) & 0x03;
                    self.nt[index] = value & 0x01;
                }
            }
            0xE000..=0xFFFF => {
                let bank = (address >> 12) & 0x0F;
                if bank == 0x0F && address & 0x0800 != 0 {
                    self.chip_addr = value & 0x7F;
                    self.chip_inc = value & 0x80 != 0;
                } else if address & 0x0400 == 0 {
                    let index = usize::from(((bank & 1) << 1) | ((address >> 11) & 1)) & 0x03;
                    if index < 3 {
                        self.prg_banks[index] = value;
                    }
                }
            }
            _ => {}
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x4800, 0x4FFF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        Mirroring::FourScreen
    }

    fn nametable_map(&self) -> Option<[u8; 4]> {
        Some(self.nt)
    }

    fn number(&self) -> u16 {
        330
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x8000..=0xBFFF).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if self.irq_counter & 0x8000 != 0 {
            self.irq_counter = self.irq_counter.wrapping_add(1);
            if self.irq_counter == 0 {
                self.irq_pending = true;
            }
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Double Dragon pirate board (mapper 127): four 8 KiB PRG windows, eight
/// 1 KiB CHR registers, per-quadrant CIRAM selection and a 256-cycle IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct DdPirate127 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 4],
    chr_banks: [u8; 8],
    mirror: [u8; 4],
    irq_enabled: bool,
    irq_counter: u8,
    irq_pending: bool,
}

impl DdPirate127 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, _header: Header) -> Self {
        Self {
            prg,
            chr,
            prg_banks: [0x0F; 4],
            chr_banks: [0; 8],
            mirror: [0; 4],
            irq_enabled: false,
            irq_counter: 0,
            irq_pending: false,
        }
    }
}

impl Mapper for DdPirate127 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let banks = (self.prg.len() / 0x2000).max(1);
        let bank = usize::from(self.prg_banks[slot]) % banks;
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0x73 {
            0x00..=0x02 => self.prg_banks[usize::from(address & 0x03)] = value & 0x0F,
            0x03 => self.prg_banks[3] = (value & 0x03) | 0x0C,
            0x10..=0x13 => self.chr_banks[usize::from(address & 0x03)] = value & 0x7F,
            0x20..=0x23 => {
                self.chr_banks[4 + usize::from(address & 0x03)] = value & 0x7F;
            }
            0x30..=0x33 => self.irq_enabled = true,
            0x40..=0x43 => {
                self.irq_enabled = false;
                self.irq_counter = 0;
                self.irq_pending = false;
            }
            0x50..=0x53 => self.mirror[usize::from(address & 0x03)] = value & 0x01,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        Mirroring::FourScreen
    }

    fn nametable_map(&self) -> Option<[u8; 4]> {
        Some(self.mirror)
    }

    fn number(&self) -> u16 {
        127
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        matches!(address & 0x73, 0x10..=0x23)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled {
            return;
        }
        self.irq_counter = self.irq_counter.wrapping_sub(1);
        if self.irq_counter == 0 {
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Conta/Gryzor bootleg (mapper 326): four 8 KiB PRG windows, eight 1 KiB CHR
/// registers and four per-quadrant CIRAM selections from CHR registers 8-11.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Gryzor326 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 4],
    chr_regs: [u8; 16],
    mirroring: Mirroring,
}

impl Gryzor326 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        let mut chr_regs = [0u8; 16];
        for (i, reg) in chr_regs.iter_mut().enumerate() {
            *reg = i as u8;
        }
        Self {
            prg,
            chr,
            prg_banks: [0xFC, 0xFD, 0xFE, 0xFF],
            chr_regs,
            mirroring: header.mirroring,
        }
    }
}

impl Mapper for Gryzor326 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let banks = (self.prg.len() / 0x2000).max(1);
        let bank = usize::from(self.prg_banks[slot]) % banks;
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0xE010 {
            0x8000 => self.prg_banks[0] = value,
            0xA000 => self.prg_banks[1] = value,
            0xC000 => self.prg_banks[2] = value,
            _ => {}
        }
        if address & 0x8010 == 0x8010 {
            self.chr_regs[usize::from(address & 0x0F)] = value;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_regs[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.chr.len() / 0x400).max(1);
        let bank = usize::from(self.chr_regs[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn nametable_map(&self) -> Option<[u8; 4]> {
        Some([
            self.chr_regs[8] & 0x01,
            self.chr_regs[9] & 0x01,
            self.chr_regs[10] & 0x01,
            self.chr_regs[11] & 0x01,
        ])
    }

    fn number(&self) -> u16 {
        326
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address & 0x8010 == 0x8010
    }
}

/// AVE NINA-118 register board: used by 418 (820106-C/821007C) and 557
/// (NTDEC 2718). A pointer/data pair at `$8000-$9FFF` selects four 8 KiB
/// PRG windows, with 8 KiB CHR-RAM and mirroring from register 5.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct N118 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    pointer: u8,
    reg: [u8; 8],
    mirror_mask: u8,
    board: u16,
}

impl N118 {
    fn new(
        prg: Vec<u8>,
        chr: Vec<u8>,
        prg_ram: Vec<u8>,
        header: Header,
        mirror_mask: u8,
        board: u16,
    ) -> Self {
        let _ = header;
        Self {
            prg,
            chr,
            prg_ram,
            pointer: 0,
            reg: [0x00, 0x02, 0x04, 0x05, 0x06, 0x07, 0x00, 0x01],
            mirror_mask,
            board,
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get(((bank & 0x0F) % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for N118 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x7FFF if !self.prg_ram.is_empty() => {
                self.prg_ram[usize::from(address - 0x6000) % self.prg_ram.len()]
            }
            0x8000..=0x9FFF => self.prg_8k(usize::from(self.reg[6]), address),
            0xA000..=0xBFFF => self.prg_8k(usize::from(self.reg[7]), address),
            0xC000..=0xDFFF => self.prg_8k(0x0E, address),
            0xE000..=0xFFFF => self.prg_8k(0x0F, address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000..=0x7FFF if !self.prg_ram.is_empty() => {
                let index = usize::from(address - 0x6000) % self.prg_ram.len();
                self.prg_ram[index] = value;
            }
            0x8000..=0x9FFF => {
                if address & 0x01 == 0 {
                    self.pointer = value;
                } else {
                    self.reg[usize::from(self.pointer & 0x07)] = value;
                }
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        if self.reg[5] & self.mirror_mask != 0 {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        }
    }

    fn number(&self) -> u16 {
        self.board
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }
}

/// Fukutake Shoten Study Box (mapper 186): a 16 KiB PRG bank, fixed bank 0 at
/// `$C000`, 8 KiB CHR-RAM and a banked 8 KiB work-RAM window, with the
/// control registers in `$4200-$4203` and work RAM at `$4400-$4FFF`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct StudyBox186 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    wram: Vec<u8>,
    reg: [u8; 4],
    mirroring: Mirroring,
}

impl StudyBox186 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut wram: Vec<u8>, header: Header) -> Self {
        wram.resize(0x8000, 0);
        Self {
            prg,
            chr,
            wram,
            reg: [0; 4],
            mirroring: header.mirroring,
        }
    }

    fn wram_bank(&self) -> usize {
        usize::from(self.reg[0] >> 6)
    }
}

impl Mapper for StudyBox186 {
    fn prg_read(&self, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        match address {
            0x6000..=0x7FFF => {
                let base = self.wram_bank() * 0x2000;
                self.wram[base + usize::from(address - 0x6000)]
            }
            0x8000..=0xBFFF => {
                let bank = usize::from(self.reg[1]) % banks;
                self.prg
                    .get(bank * 0x4000 + usize::from(address & 0x3FFF))
                    .copied()
                    .unwrap_or(0)
            }
            0xC000..=0xFFFF => self
                .prg
                .get(usize::from(address - 0xC000))
                .copied()
                .unwrap_or(0),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x4200..=0x4203 => self.reg[usize::from(address & 0x03)] = value,
            0x4400..=0x4FFF => {
                let base = self.wram_bank() * 0x2000;
                self.wram[base + (usize::from(address) & 0x0FFF) - 0x400] = value;
            }
            0x6000..=0x7FFF => {
                let base = self.wram_bank() * 0x2000;
                self.wram[base + usize::from(address - 0x6000)] = value;
            }
            _ => {}
        }
    }

    fn read_io(&mut self, address: u16) -> u8 {
        match address {
            0x4202 => 0x40,
            0x4200..=0x4203 => 0x00,
            0x4400..=0x4FFF => {
                let base = self.wram_bank() * 0x2000;
                self.wram[base + (usize::from(address) & 0x0FFF) - 0x400]
            }
            _ => self.prg_read(address),
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x4200, 0x4FFF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        186
    }

    fn prg_ram(&self) -> &[u8] {
        &self.wram
    }
}

/// Realtec HSK007 multicart (mapper 394): an MMC3 clone inside a switchable
/// 256 KiB PRG/CHR slice, with a `$5009` mode register (`$0F` at power-on
/// selects MMC3) and a `$500B` outer-bank register. BNROM mode uses a single
/// 32 KiB bank built from both registers.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Hsk007 {
    inner: Mmc3,
    mode: u8,
    outer: u8,
    submap: u8,
}

impl Hsk007 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            inner: Mmc3::new_as(prg, chr, header, 394),
            mode: 0x0F,
            outer: 0x90,
            submap: header.submapper,
        }
    }

    fn mode_bits(&self) -> u8 {
        (self.mode >> 3) & 0x03
    }

    /// 256 KiB PRG slice, in 8 KiB banks.
    fn prg_outer(&self) -> usize {
        let a18 = usize::from(self.mode & 0x01);
        let a19 = usize::from((self.mode >> 1) & 0x01);
        ((a19 << 1) | a18) * 32
    }

    /// 256 KiB CHR slice, in 1 KiB banks.
    fn chr_outer(&self) -> usize {
        let a18 = if self.submap == 0 {
            usize::from(self.mode & 0x01)
        } else {
            usize::from((self.mode >> 2) & 0x01)
        };
        let a19 = usize::from((self.mode >> 1) & 0x01);
        ((a19 << 1) | a18) * 256
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.inner.prg.len() / 0x2000).max(1);
        self.inner
            .prg
            .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_32k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.inner.prg.len() / 0x8000).max(1);
        self.inner
            .prg
            .get((bank % banks) * 0x8000 + usize::from(address & 0x7FFF))
            .copied()
            .unwrap_or(0)
    }

    /// BNROM 32 KiB bank from the two registers.
    fn bnrom_bank(&self) -> usize {
        let a18 = usize::from(self.mode & 0x01);
        let a19 = usize::from((self.mode >> 1) & 0x01);
        let a17 = usize::from((self.outer >> 3) & 0x01);
        let a16 = usize::from((self.outer >> 2) & 0x01);
        let a15 = usize::from((self.outer >> 1) & 0x01);
        (a19 << 4) | (a18 << 3) | (a17 << 2) | (a16 << 1) | a15
    }
}

impl Mapper for Hsk007 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return self.inner.prg_read(address);
        }
        match self.mode_bits() {
            0 => self.prg_32k(self.bnrom_bank(), address),
            _ => {
                let slot = usize::from((address - 0x8000) / 0x2000);
                let bank = self.prg_outer() + self.inner.prg_slot_in(slot, 32);
                self.prg_8k(bank, address)
            }
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x5009 => self.mode = value,
            0x500B => self.outer = value,
            _ => self.inner.prg_write(address, value),
        }
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x5000, 0x5FFF))
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let bank = self.chr_outer() + self.inner.chr_bank_in(slot, 256);
        self.inner
            .chr
            .get((bank % banks) * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let bank = self.chr_outer() + self.inner.chr_bank_in(slot, 256);
        if let Some(byte) = self
            .inner
            .chr
            .get_mut((bank % banks) * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        394
    }

    fn prg_ram(&self) -> &[u8] {
        &self.inner.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x5009..=0x500B).contains(&address) || self.inner.chr_mapping_write(address)
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }
}

/// 5/20-in-1 1993 multicart (mapper 334): MMC3 supplies CHR banking,
/// mirroring and IRQs, while a `$6000` register selects one 32 KiB PRG bank.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mmc3_334 {
    inner: Mmc3,
    prg_bank: u8,
}

impl Mmc3_334 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            inner: Mmc3::new_as(prg, chr, header, 334),
            prg_bank: 0,
        }
    }

    fn prg_32k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.inner.prg.len() / 0x8000).max(1);
        self.inner
            .prg
            .get((bank % banks) * 0x8000 + usize::from(address - 0x8000))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Mmc3_334 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6002 => 0x01,
            0x6000..=0x7FFF => self.inner.prg_read(address),
            0x8000..=0xFFFF => self.prg_32k(usize::from(self.prg_bank & 0x03), address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000 => {
                if self.inner.ram_enabled {
                    self.prg_bank = (value >> 2) & 0x03;
                }
            }
            0x6001 | 0x6002 => {}
            _ => self.inner.prg_write(address, value),
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.inner.chr_read(address)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        self.inner.chr_write(address, value);
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        334
    }

    fn prg_ram(&self) -> &[u8] {
        &self.inner.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        self.inner.chr_mapping_write(address)
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }
}

/// Kaiser KS7012 (mapper 346): two fixed 32 KiB PRG pages selected by magic
/// writes, with fixed 8 KiB CHR.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Ks7012 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    page: u8,
    mirroring: Mirroring,
}

impl Ks7012 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            page: 1,
            mirroring: header.mirroring,
        }
    }

    fn prg_32k(&self, page: usize, address: u16) -> u8 {
        let pages = (self.prg.len() / 0x8000).max(1);
        self.prg
            .get((page % pages) * 0x8000 + usize::from(address - 0x8000))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Ks7012 {
    fn prg_read(&self, address: u16) -> u8 {
        if address >= 0x8000 {
            self.prg_32k(usize::from(self.page), address)
        } else if (0x6000..=0x7FFF).contains(&address) {
            self.prg_ram[usize::from(address - 0x6000) % self.prg_ram.len()]
        } else {
            0
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000..=0x7FFF => {
                let index = usize::from(address - 0x6000) % self.prg_ram.len();
                self.prg_ram[index] = value;
            }
            0xE0A0 => self.page = 0,
            0xEE36 => self.page = 1,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        346
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }
}

/// Kaiser KS7057 (mapper 302): 2 KiB PRG pages, four switchable 8 KiB
/// windows at `$8000`/`$A000`/`$C000`/`$E000`, four 2 KiB ROM windows at
/// `$6000-$7FFF` and register-select mirroring.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Ks7057 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    regs: [u8; 8],
    mirroring: Mirroring,
}

impl Ks7057 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            regs: [0; 8],
            mirroring: header.mirroring,
        }
    }

    fn prg_2k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x800).max(1);
        self.prg
            .get((bank % banks) * 0x800 + usize::from(address & 0x7FF))
            .copied()
            .unwrap_or(0)
    }

    fn slot_page(&self, slot: usize) -> usize {
        if slot < 4 {
            usize::from(self.regs[slot])
        } else {
            0x30 + (slot & 0x0C) + (slot & 0x03)
        }
    }

    fn set_reg(&mut self, index: usize, value: u8, low: bool) {
        if low {
            self.regs[index] = (self.regs[index] & 0xF0) | (value & 0x0F);
        } else {
            self.regs[index] = (self.regs[index] & 0x0F) | ((value << 4) & 0xF0);
        }
    }
}

impl Mapper for Ks7057 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x7FFF => {
                let index = usize::from(address - 0x6000) / 0x800;
                self.prg_2k(usize::from(self.regs[4 + index]), address)
            }
            0x8000..=0xFFFF => {
                let slot = usize::from(address - 0x8000) / 0x800;
                self.prg_2k(self.slot_page(slot), address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        let low = address & 0x01 == 0;
        match address & 0xF002 {
            0x8000 | 0x8002 | 0x9000 | 0x9002 => {
                self.mirroring = if value & 0x01 != 0 {
                    Mirroring::Vertical
                } else {
                    Mirroring::Horizontal
                };
            }
            0xB000 => self.set_reg(0, value, low),
            0xB002 => self.set_reg(1, value, low),
            0xC000 => self.set_reg(2, value, low),
            0xC002 => self.set_reg(3, value, low),
            0xD000 => self.set_reg(4, value, low),
            0xD002 => self.set_reg(5, value, low),
            0xE000 => self.set_reg(6, value, low),
            0xE002 => self.set_reg(7, value, low),
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        302
    }

    fn prg_rom_at_6000(&self) -> bool {
        true
    }
}

/// Kaiser KS7037 (mapper 307): 4 KiB PRG banking, 8 KiB CHR, a 4 KiB WRAM
/// window at `$6000` and 16 KiB windows at `$8000`/`$C000`/`$E000`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Ks7037 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    regs: [u8; 8],
    select: u8,
    mirroring: Mirroring,
}

impl Ks7037 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            regs: [0; 8],
            select: 0,
            mirroring: header.mirroring,
        }
    }

    fn prg_4k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x1000).max(1);
        self.prg
            .get((bank % banks) * 0x1000 + usize::from(address & 0x0FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Ks7037 {
    fn prg_read(&self, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x1000).max(1);
        match address {
            0x6000..=0x6FFF => self.prg_ram[usize::from(address - 0x6000)],
            0x7000..=0x7FFF => self.prg_4k(15, address),
            0x8000..=0x9FFF => {
                let bank = usize::from(self.regs[6]) * 2 + usize::from((address >> 12) & 1);
                self.prg_4k(bank, address)
            }
            0xA000..=0xAFFF => self.prg_4k(banks.saturating_sub(4), address),
            0xB000..=0xBFFF => self.prg_ram[0x1000 + (usize::from(address - 0xB000) & 0x0FFF)],
            0xC000..=0xDFFF => {
                let bank = usize::from(self.regs[7]) * 2 + usize::from((address >> 12) & 1);
                self.prg_4k(bank, address)
            }
            0xE000..=0xFFFF => {
                let bank = banks.saturating_sub(2) + usize::from((address >> 12) & 1);
                self.prg_4k(bank, address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0xE001 {
            0x8000 => self.select = value & 0x07,
            0x8001 => self.regs[usize::from(self.select & 0x07)] = value,
            _ => {}
        }
        if (0x6000..=0x6FFF).contains(&address) {
            self.prg_ram[usize::from(address - 0x6000)] = value;
        } else if (0xB000..=0xBFFF).contains(&address) {
            let index = 0x1000 + (usize::from(address - 0xB000) & 0x0FFF);
            if let Some(byte) = self.prg_ram.get_mut(index) {
                *byte = value;
            }
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        307
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }
}

/// Shared CHR/nametable state for the Irem 77 board: 2 KiB switchable
/// CHR-ROM, 6 KiB CHR-RAM and 4 KiB of cartridge nametable RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Aux77 {
    rom: Vec<u8>,
    ram: Vec<u8>,
    #[serde(with = "serde_big_array::BigArray")]
    nt: [u8; 0x1000],
    chr_bank: u8,
}

impl Aux77 {
    fn new(rom: Vec<u8>) -> Self {
        Self {
            rom,
            ram: vec![0; 0x1800],
            nt: [0; 0x1000],
            chr_bank: 0,
        }
    }

    pub(crate) fn chr_read(&self, address: u16) -> u8 {
        let address = address & 0x1FFF;
        if address < 0x800 {
            let banks = (self.rom.len() / 0x800).max(1);
            let bank = usize::from(self.chr_bank) % banks;
            self.rom
                .get(bank * 0x800 + usize::from(address))
                .copied()
                .unwrap_or(0)
        } else {
            self.ram
                .get(usize::from(address - 0x800))
                .copied()
                .unwrap_or(0)
        }
    }

    pub(crate) fn chr_write(&mut self, address: u16, value: u8) {
        let address = address & 0x1FFF;
        if address >= 0x800 {
            if let Some(byte) = self.ram.get_mut(usize::from(address - 0x800)) {
                *byte = value;
            }
        }
    }

    pub(crate) fn nt_read(&self, address: u16) -> u8 {
        self.nt[usize::from(address & 0x0FFF)]
    }

    pub(crate) fn nt_write(&mut self, address: u16, value: u8) {
        self.nt[usize::from(address & 0x0FFF)] = value;
    }
}

/// Irem (mapper 77, Napoleon Senki): 32 KiB PRG banking with bus conflicts,
/// 2 KiB CHR-ROM + 6 KiB CHR-RAM and 4 KiB cartridge nametable RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Irem77 {
    prg: Vec<u8>,
    aux: Rc<RefCell<Aux77>>,
    prg_bank: u8,
}

impl Irem77 {
    fn new(prg: Vec<u8>, chr: Vec<u8>) -> Self {
        Self {
            prg,
            aux: Rc::new(RefCell::new(Aux77::new(chr))),
            prg_bank: 0,
        }
    }

    fn prg_32k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x8000).max(1);
        self.prg
            .get((bank % banks) * 0x8000 + usize::from(address - 0x8000))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Irem77 {
    fn prg_read(&self, address: u16) -> u8 {
        if address >= 0x8000 {
            self.prg_32k(usize::from(self.prg_bank), address)
        } else {
            0
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            let effective = value & self.prg_read(address);
            self.prg_bank = effective & 0x0F;
            self.aux.borrow_mut().chr_bank = (effective >> 4) & 0x0F;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.aux.borrow().chr_read(address)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        self.aux.borrow_mut().chr_write(address, value);
    }

    fn mirroring(&self) -> Mirroring {
        Mirroring::FourScreen
    }

    fn number(&self) -> u16 {
        77
    }

    fn aux77(&self) -> Option<Rc<RefCell<Aux77>>> {
        Some(self.aux.clone())
    }
}

/// Kaiser KS202 (mapper 56): four 8 KiB PRG banks, eight 1 KiB CHR banks,
/// a WRAM/ROM window at `$6000` and the Kaiser 16-bit cycle IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Ks202 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    prg_banks: [u8; 4],
    chr_banks: [u8; 8],
    select: u8,
    use_rom: bool,
    mirroring: Mirroring,
    irq_reload: u16,
    irq_counter: u16,
    irq_control: u8,
    irq_pending: bool,
}

impl Ks202 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            prg_banks: [0; 4],
            chr_banks: [0; 8],
            select: 0,
            use_rom: false,
            mirroring: header.mirroring,
            irq_reload: 0,
            irq_counter: 0,
            irq_control: 0,
            irq_pending: false,
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get((bank % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Ks202 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x7FFF => {
                if self.use_rom {
                    self.prg_8k(usize::from(self.prg_banks[3]), address)
                } else {
                    self.prg_ram[usize::from(address - 0x6000)]
                }
            }
            0x8000..=0x9FFF => self.prg_8k(usize::from(self.prg_banks[0]), address),
            0xA000..=0xBFFF => self.prg_8k(usize::from(self.prg_banks[1]), address),
            0xC000..=0xDFFF => self.prg_8k(usize::from(self.prg_banks[2]), address),
            0xE000..=0xFFFF => {
                let last = (self.prg.len() / 0x2000).max(1) - 1;
                self.prg_8k(last, address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000..=0x7FFF => {
                if !self.use_rom {
                    self.prg_ram[usize::from(address - 0x6000)] = value;
                }
            }
            0x8000..=0x8FFF => {
                self.irq_reload = (self.irq_reload & 0xFFF0) | u16::from(value & 0x0F)
            }
            0x9000..=0x9FFF => {
                self.irq_reload = (self.irq_reload & 0xFF0F) | (u16::from(value & 0x0F) << 4)
            }
            0xA000..=0xAFFF => {
                self.irq_reload = (self.irq_reload & 0xF0FF) | (u16::from(value & 0x0F) << 8)
            }
            0xB000..=0xBFFF => {
                self.irq_reload = (self.irq_reload & 0x0FFF) | (u16::from(value & 0x0F) << 12)
            }
            0xC000..=0xCFFF => {
                self.irq_control = value;
                if value & 0x02 != 0 {
                    self.irq_counter = self.irq_reload;
                }
                self.irq_pending = false;
            }
            0xD000..=0xDFFF => self.irq_pending = false,
            0xE000..=0xEFFF => self.select = (value & 0x07).wrapping_sub(1),
            0xF000..=0xF3FF => {
                match self.select {
                    0..=3 => {
                        let index = usize::from(self.select);
                        self.prg_banks[index] = (self.prg_banks[index] & 0x10) | (value & 0x0F);
                    }
                    4 => self.use_rom = value & 0x04 != 0,
                    _ => {}
                }
                let bank = usize::from(address & 0x03);
                self.prg_banks[bank] = (value & 0x10) | (self.prg_banks[bank] & 0x0F);
            }
            0xF800..=0xFBFF => {
                self.mirroring = if value & 0x01 != 0 {
                    Mirroring::Vertical
                } else {
                    Mirroring::Horizontal
                };
            }
            0xFC00..=0xFFFF => {
                self.chr_banks[usize::from(address & 0x07)] = value;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from(address) / 0x400;
        let bank = usize::from(self.chr_banks[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from(address) / 0x400;
        let bank = usize::from(self.chr_banks[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        56
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if self.irq_control & 0x02 == 0 {
            return;
        }
        self.irq_counter = self.irq_counter.wrapping_add(1);
        if self.irq_counter == 0xFFFF {
            self.irq_counter = self.irq_reload;
            self.irq_control &= !0x02;
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Konami VRC3 (mapper 73): a 16 KiB switchable PRG bank, 8 KiB CHR-RAM and
/// a 16-bit CPU-cycle IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Vrc3_73 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    /// Outer PRG base and inner mask in 16 KiB units (446 supervisor).
    prg_outer: usize,
    prg_mask: usize,
    prg_bank: u8,
    mirroring: Mirroring,
    irq_latch: u16,
    irq_counter: u16,
    irq_enabled: bool,
    irq_pending: bool,
}

impl Vrc3_73 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, mut prg_ram: Vec<u8>, header: Header) -> Self {
        prg_ram.resize(0x2000, 0);
        Self {
            prg,
            chr,
            prg_ram,
            prg_outer: 0,
            prg_mask: usize::MAX,
            prg_bank: 0,
            mirroring: header.mirroring,
            irq_latch: 0,
            irq_counter: 0,
            irq_enabled: false,
            irq_pending: false,
        }
    }

    fn prg_16k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Vrc3_73 {
    /// Applies the mapper-446 supervisor's outer PRG base and inner mask.
    /// Both are in 16 KiB units for this board.
    pub(crate) fn set_prg_outer(&mut self, outer: usize, mask: usize) {
        self.prg_outer = outer;
        self.prg_mask = mask;
    }
}

impl Mapper for Vrc3_73 {
    fn prg_read(&self, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        match address {
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)],
            0x8000..=0xBFFF => {
                let bank = ((usize::from(self.prg_bank) & self.prg_mask) | self.prg_outer) % banks;
                self.prg_16k(bank, address)
            }
            0xC000..=0xFFFF => {
                let bank = (((banks - 1) & self.prg_mask) | self.prg_outer) % banks;
                self.prg_16k(bank, address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x6000..=0x7FFF => self.prg_ram[usize::from(address - 0x6000)] = value,
            0x8000..=0x8FFF => self.irq_latch = (self.irq_latch & 0xFFF0) | u16::from(value & 0x0F),
            0x9000..=0x9FFF => {
                self.irq_latch = (self.irq_latch & 0xFF0F) | (u16::from(value & 0x0F) << 4)
            }
            0xA000..=0xAFFF => {
                self.irq_latch = (self.irq_latch & 0xF0FF) | (u16::from(value & 0x0F) << 8)
            }
            0xB000..=0xBFFF => {
                self.irq_latch = (self.irq_latch & 0x0FFF) | (u16::from(value & 0x0F) << 12)
            }
            0xC000..=0xCFFF => {
                self.irq_enabled = value & 0x02 != 0;
                self.irq_pending = false;
                if self.irq_enabled {
                    self.irq_counter = self.irq_latch;
                }
            }
            0xD000..=0xDFFF => {
                self.irq_pending = false;
                self.irq_enabled = false;
            }
            0xF000..=0xFFFF => self.prg_bank = value & 0x07,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        73
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled {
            return;
        }
        if self.irq_counter == 0 {
            self.irq_counter = self.irq_latch;
            self.irq_pending = true;
        } else {
            self.irq_counter -= 1;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

