/// Sachen 9602 (mapper 513): an MMC3-derived ASIC with an outer PRG bank
/// register, top banks fixed inside the selected 256 KiB block, and 8 KiB
/// CHR-RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Sachen9602 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    mirroring: Mirroring,
    regs: [u8; 8],
    bank_select: u8,
    prg_mode: bool,
    irq_counter: u8,
    irq_latch: u8,
    irq_reload: bool,
    irq_enabled: bool,
    irq_pending: bool,
}

impl Sachen9602 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            mirroring: header.mirroring,
            regs: [0; 8],
            bank_select: 0,
            prg_mode: false,
            irq_counter: 0,
            irq_latch: 0,
            irq_reload: false,
            irq_enabled: false,
            irq_pending: false,
        }
    }

    fn prg_bank(&self, slot: usize) -> usize {
        let banks = (self.prg.len() / 0x2000).max(1);
        // NRS: slots 0/1 ($8000/$A000) take the outer bits from MMC3 R0;
        // slots 2/3 are the fixed 0x3E/0x3F banks with no outer bits.
        let raw = match (slot, self.prg_mode) {
            (0, false) => usize::from(self.regs[6] & 0x3F),
            (1, false) => usize::from(self.regs[7] & 0x3F),
            (2, false) => 0x3E,
            (3, false) => 0x3F,
            (0, true) => 0x3E,
            (1, true) => usize::from(self.regs[7] & 0x3F),
            (2, true) => usize::from(self.regs[6] & 0x3F),
            _ => 0x3F,
        };
        let outer = if slot < 2 {
            usize::from(self.regs[0]) & 0xC0
        } else {
            0
        };
        (raw | outer) % banks
    }

    fn write_mmc3(&mut self, address: u16, value: u8) {
        match address & 0xE001 {
            0x8000 => {
                self.bank_select = value & 0x07;
                self.prg_mode = value & 0x40 != 0;
            }
            0x8001 => {
                // R0 keeps its high bits: they are the outer PRG bank for
                // the $8000/$A000 slots.
                self.regs[usize::from(self.bank_select)] = value;
            }
            0xA000 => {
                self.mirroring = if value & 0x01 == 0 {
                    Mirroring::Vertical
                } else {
                    Mirroring::Horizontal
                };
            }
            0xC000 => self.irq_latch = value,
            0xC001 => {
                self.irq_counter = 0;
                self.irq_reload = true;
            }
            0xE000 => {
                self.irq_enabled = false;
                self.irq_pending = false;
            }
            0xE001 => self.irq_enabled = true,
            _ => {}
        }
    }
}

impl Mapper for Sachen9602 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = self.prg_bank(slot);
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.write_mmc3(address, value);
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        513
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_scanline(&mut self) {
        if self.irq_counter == 0 || self.irq_reload {
            self.irq_counter = self.irq_latch;
            self.irq_reload = false;
        } else {
            self.irq_counter = self.irq_counter.wrapping_sub(1);
        }
        if self.irq_counter == 0 && self.irq_enabled {
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Later Kaiser boards (mappers 305, 306 and 312) sharing the KS-7017 family:
/// small-window PRG banking with a fixed last 32 KiB (305/306) or a switchable
/// 16 KiB half (312), CHR-RAM, and board-specific address decodes.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct KaiserMisc {
    prg: Vec<u8>,
    chr: Vec<u8>,
    board: u16,
    regs4: [u8; 4],
    win_6000: u8,
    prg16: u8,
    mirroring: Mirroring,
}

impl KaiserMisc {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header, board: u16) -> Self {
        Self {
            prg,
            chr,
            board,
            regs4: [0; 4],
            win_6000: 8,
            prg16: 0,
            mirroring: header.mirroring,
        }
    }

    fn read_2k(&self, bank: usize, address: u16) -> u8 {
        let count = (self.prg.len() / 0x800).max(1);
        self.prg
            .get((bank % count) * 0x800 + usize::from(address & 0x7FF))
            .copied()
            .unwrap_or(0)
    }

    fn read_8k(&self, bank: usize, address: u16) -> u8 {
        let count = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get((bank % count) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for KaiserMisc {
    fn prg_read(&self, address: u16) -> u8 {
        match self.board {
            305 => match address {
                0x6000..=0x7FFF => {
                    let win = usize::from(address - 0x6000) / 0x800;
                    self.read_2k(usize::from(self.regs4[win]), address)
                }
                0x8000..=0xFFFF => {
                    // The 32 KiB bank at $8000 exposes its 16 x 2 KiB pages
                    // in reverse order (window 0 = page 15).
                    let win = usize::from(address - 0x8000) / 0x800;
                    self.read_2k(15 - win, address)
                }
                _ => 0,
            },
            306 => match address {
                0x6000..=0x7FFF => self.read_8k(usize::from(self.win_6000), address),
                0x8000..=0xFFFF => {
                    let count = (self.prg.len() / 0x2000).max(1);
                    let win = usize::from(address - 0x8000) / 0x2000;
                    self.read_8k(count.saturating_sub(4) + win, address)
                }
                _ => 0,
            },
            312 => match address {
                0x8000..=0xBFFF => {
                    let banks = (self.prg.len() / 0x4000).max(1);
                    let bank = usize::from(self.prg16) % banks;
                    self.prg
                        .get(bank * 0x4000 + usize::from(address & 0x3FFF))
                        .copied()
                        .unwrap_or(0)
                }
                0xC000..=0xFFFF => {
                    let banks = (self.prg.len() / 0x4000).max(1);
                    self.prg
                        .get((banks - 1) * 0x4000 + usize::from(address & 0x3FFF))
                        .copied()
                        .unwrap_or(0)
                }
                _ => 0,
            },
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match self.board {
            305 => {
                if address >= 0x8000 {
                    self.regs4[usize::from((address >> 11) & 0x03)] = value & 0x3F;
                }
            }
            306 => {
                if address >= 0x8000 {
                    // The register value comes from the write *address*.
                    let mode = address & 0x30 == 0x30;
                    match address & 0xD943 {
                        0xD943 => {
                            self.win_6000 = if mode {
                                0x0B
                            } else {
                                ((address >> 2) & 0x0F) as u8
                            };
                        }
                        0xD903 => {
                            self.win_6000 = if mode {
                                0x08 | ((address >> 2) & 0x03) as u8
                            } else {
                                0x0B
                            };
                        }
                        _ => {}
                    }
                }
            }
            312 => {
                if address >= 0x8000 {
                    self.mirroring = if value & 0x01 != 0 {
                        Mirroring::Horizontal
                    } else {
                        Mirroring::Vertical
                    };
                } else if (0x6000..=0x7FFF).contains(&address) {
                    self.prg16 = value;
                }
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        self.board
    }

    fn prg_rom_at_6000(&self) -> bool {
        matches!(self.board, 305 | 306)
    }
}

/// NTDEC N625092 (mapper 221): address-decoded 16 KiB PRG windows with a
/// switchable NROM/UNROM/NROM-256 mode and flat 8 KiB CHR-RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Ntdec221 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    mirroring: Mirroring,
    mode: u16,
    prg_reg: u8,
    prg0: usize,
    prg1: usize,
}

impl Ntdec221 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        let mut this = Self {
            prg,
            chr,
            mirroring: header.mirroring,
            mode: 0,
            prg_reg: 0,
            prg0: 0,
            prg1: 0,
        };
        this.update_state();
        this
    }

    fn update_state(&mut self) {
        let outer = usize::from((self.mode & 0xFC) >> 2);
        let reg = usize::from(self.prg_reg);
        if self.mode & 0x02 != 0 {
            if self.mode & 0x0100 != 0 {
                self.prg0 = outer | reg;
                self.prg1 = outer | 0x07;
            } else {
                let bank = outer | (reg & 0x06);
                self.prg0 = bank;
                self.prg1 = bank | 1;
            }
        } else {
            self.prg0 = outer | reg;
            self.prg1 = self.prg0;
        }
        self.mirroring = if self.mode & 0x01 != 0 {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        };
    }

    fn prg_read_16k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Ntdec221 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x8000..=0xBFFF => self.prg_read_16k(self.prg0, address),
            0xC000..=0xFFFF => self.prg_read_16k(self.prg1, address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, _value: u8) {
        match address & 0xC000 {
            0x8000 => self.mode = address,
            0xC000 => self.prg_reg = (address & 0x07) as u8,
            _ => return,
        }
        self.update_state();
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        221
    }
}

/// BMC 31-in-1 (mapper 229): an address-latched 16 KiB PRG bank mirrored over
/// both halves, a fixed 32 KiB NROM menu bank, and 8 KiB CHR-ROM banks.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Multicart229 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    latch: u8,
    chr_bank: u8,
    mirroring: Mirroring,
}

impl Multicart229 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            latch: 0,
            chr_bank: 0,
            mirroring: header.mirroring,
        }
    }

    fn prg_16k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Multicart229 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        if self.latch & 0x1E == 0 {
            self.prg_16k(usize::from(address >= 0xC000), address)
        } else {
            self.prg_16k(usize::from(self.latch & 0x1F), address)
        }
    }

    fn prg_write(&mut self, address: u16, _value: u8) {
        if address >= 0x8000 {
            self.latch = (address & 0x3F) as u8;
            self.chr_bank = (address & 0xFF) as u8;
            self.mirroring = if address & 0x20 != 0 {
                Mirroring::Horizontal
            } else {
                Mirroring::Vertical
            };
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        self.chr
            .get((usize::from(self.chr_bank) % banks) * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let index = (usize::from(self.chr_bank) % banks) * 0x2000 + usize::from(address & 0x1FFF);
        if let Some(byte) = self.chr.get_mut(index) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        229
    }
}

/// BMC-60311C (mapper 289): a $6000/$6001 mode/outer latch plus a $8000 inner
/// bank register, selecting 16 KiB PRG windows and flat 8 KiB CHR-RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Bmc289 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    mode: u8,
    outer: u8,
    inner: u8,
    prg0: usize,
    prg1: usize,
    mirroring: Mirroring,
}

impl Bmc289 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        let mut this = Self {
            prg,
            chr,
            mode: 0,
            outer: 0,
            inner: 0,
            prg0: 0,
            prg1: 0,
            mirroring: header.mirroring,
        };
        this.update_state();
        this
    }

    fn update_state(&mut self) {
        let page = usize::from(self.outer)
            | if self.mode & 0x04 != 0 {
                0
            } else {
                usize::from(self.inner)
            };
        match self.mode & 0x03 {
            0 => {
                self.prg0 = page;
                self.prg1 = page;
            }
            1 => {
                let bank = page & 0xFE;
                self.prg0 = bank;
                self.prg1 = bank | 1;
            }
            2 => {
                self.prg0 = page;
                self.prg1 = usize::from(self.outer) | 7;
            }
            _ => {}
        }
        self.mirroring = if self.mode & 0x08 != 0 {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        };
    }

    fn prg_16k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Bmc289 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x8000..=0xBFFF => self.prg_16k(self.prg0, address),
            0xC000..=0xFFFF => self.prg_16k(self.prg1, address),
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.inner = value & 0x07;
        } else {
            match address & 0xE001 {
                0x6000 => self.mode = value & 0x0F,
                0x6001 => self.outer = value,
                _ => return,
            }
        }
        self.update_state();
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        289
    }
}

/// MMC3-clone multicarts (mappers 134, 205 and 238) with a board-specific
/// outer-bank transform layered over the shared MMC3 core.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mmc3Outer {
    inner: Mmc3,
    board: u16,
    outer: u8,
    security: u8,
}

impl Mmc3Outer {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header, board: u16) -> Self {
        Self {
            inner: Mmc3::new_as(prg, chr, header, board),
            board,
            outer: 0,
            security: 0,
        }
    }

    fn prg_bank(&self, slot: usize) -> usize {
        let banks = (self.inner.prg.len() / 0x2000).max(1);
        let base = self.inner.prg_slot(slot);
        let bank = match self.board {
            134 => (base & 0x1F) | (usize::from(self.outer & 0x02) << 4),
            205 => {
                let block = usize::from(self.outer & 0x03);
                (base & if block <= 1 { 0x1F } else { 0x0F }) | (block * 0x10)
            }
            // NRS syncPRG(0x0F, reg << 4): the register's high nibble
            // supplies the outer PRG bits for every slot.
            47 => (base & 0x0F) | (usize::from(self.outer) << 4),
            52 => {
                // NRS syncPRG(reg & 8 ? 0x0F : 0x1F, (reg << 4) & 0x70),
                // applied to every slot including the fixed banks.
                let or = (usize::from(self.outer) << 4) & 0x70;
                let and = if self.outer & 0x08 != 0 { 0x0F } else { 0x1F };
                (base & and) | (or & !and)
            }
            516 => (base & 0x0F) | (usize::from(self.outer & 0x03) << 4),
            _ => base,
        };
        bank % banks
    }

    fn chr_bank(&self, slot: usize) -> usize {
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let base = self.inner.chr_bank(slot);
        let bank = match self.board {
            134 => (base & 0xFF) | (usize::from(self.outer & 0x20) << 3),
            47 => (base & 0x7F) | (usize::from(self.outer) << 7),
            52 => {
                // NRS: chrOR = (reg << 3) & 0x180 | (reg << 7) & 0x200;
                // chrAND = reg & 0x40 ? 0x7F : 0xFF.
                let or = ((usize::from(self.outer) << 3) & 0x180)
                    | ((usize::from(self.outer) << 7) & 0x200);
                let and = if self.outer & 0x40 != 0 { 0x7F } else { 0xFF };
                (base & and) | (or & !and)
            }
            516 => (base & 0x7F) | ((usize::from(self.outer >> 2) & 0x03) << 7),
            205 => {
                let block = self.outer & 0x03;
                let mut page = base;
                if block >= 2 {
                    page = (page & 0x7F) | 0x100;
                }
                if block == 1 || block == 3 {
                    page |= 0x80;
                }
                page
            }
            _ => base,
        };
        bank % banks
    }
}

impl Mapper for Mmc3Outer {
    fn prg_read(&self, address: u16) -> u8 {
        if self.board == 238 && (0x4020..0x8000).contains(&address) {
            return self.security;
        }
        if address < 0x8000 {
            return self.inner.prg_read(address);
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = self.prg_bank(slot);
        self.inner
            .prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address < 0x8000 {
            match self.board {
                134 => {
                    if address == 0x6001 {
                        self.outer = value;
                    }
                }
                205 => {
                    if (0x6000..=0x7FFF).contains(&address) {
                        self.outer = value & 0x03;
                    }
                }
                238 if (0x4020..=0x7FFF).contains(&address) => {
                    const LUT: [u8; 4] = [0x00, 0x02, 0x02, 0x03];
                    self.security = LUT[usize::from(value & 0x03)];
                }
                47 => {
                    // NRS latches any $6000-$7FFF write (submapper 0).
                    if (0x6000..=0x7FFF).contains(&address) {
                        self.outer = value;
                    }
                }
                52 if (0x6000..=0x7FFF).contains(&address) && self.outer & 0x80 == 0 => {
                    self.outer = value;
                }
                _ => {}
            }
            return;
        }
        if self.board == 516 && address & 0x8010 == 0x8010 {
            self.outer = (address & 0x0F) as u8;
            return;
        }
        self.inner.prg_write(address, value);
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let bank = self.chr_bank(slot);
        self.inner
            .chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let bank = self.chr_bank(slot);
        if let Some(byte) = self
            .inner
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        self.board
    }

    fn prg_ram(&self) -> &[u8] {
        &self.inner.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x8000..=0x9FFF).contains(&address)
            || matches!(self.board, 134 if address == 0x6001)
            || matches!(self.board, 205 if (0x6000..=0x7FFF).contains(&address))
            || matches!(self.board, 516 if address & 0x8010 == 0x8010)
            || matches!(self.board, 47 | 52 if (0x6000..=0x7FFF).contains(&address))
    }

    fn prg_rom_at_6000(&self) -> bool {
        self.board == 238
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        if self.board == 238 {
            Some((0x4020, 0x5FFF))
        } else {
            None
        }
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }
}

/// CK-001 4-in-1 (mapper 301): the mapper-242 address latch extended with
/// the ET-113 style 512 KiB / 128 KiB chip select. The latch collects the
/// write address bits (chip and fixed-bank select) plus the data bits
/// (outer/inner bank, mirroring, mode), and is determined by both.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Bmc301 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    /// Latched write address bits 8-10 (m, L, C).
    latch_addr: u16,
    /// Latched data byte (O QQ PP p M S).
    latch_data: u8,
    mirroring: Mirroring,
}

impl Bmc301 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, _header: Header) -> Self {
        let chr = if chr.len() >= 0x2000 {
            chr
        } else {
            let mut ram = vec![0; 0x2000];
            let keep = chr.len().min(0x2000);
            ram[..keep].copy_from_slice(&chr[..keep]);
            ram
        };
        // Power-on: O=1, S=1 (32 KiB NROM) selects the last 32 KiB page,
        // where the menu and its reset vector live.
        Self {
            prg,
            chr,
            latch_addr: 0x0400,
            latch_data: 0xF9,
            mirroring: Mirroring::Vertical,
        }
    }

    fn chip(&self) -> (usize, usize) {
        let total = self.prg.len();
        if self.latch_addr & 0x0400 != 0 && total >= 0x80000 {
            (0, 0x80000)
        } else {
            (total.saturating_sub(0x20000), total.min(0x20000))
        }
    }

    fn inner_bank(&self) -> usize {
        let q = usize::from((self.latch_data >> 5) & 0x03);
        let p4 = usize::from((self.latch_data >> 4) & 0x01);
        let p3 = usize::from((self.latch_data >> 3) & 0x01);
        let p2 = usize::from((self.latch_data >> 2) & 0x01);
        (q << 3) | (p4 << 2) | (p3 << 1) | p2
    }

    fn read_bank(&self, bank: usize, address: u16) -> u8 {
        let (base, size) = self.chip();
        let banks = (size / 0x4000).max(1);
        let offset = base + (bank % banks) * 0x4000 + usize::from(address & 0x3FFF);
        self.prg.get(offset).copied().unwrap_or(0)
    }

    fn read_bank32(&self, bank: usize, address: u16) -> u8 {
        let (base, size) = self.chip();
        let banks = (size / 0x8000).max(1);
        let offset = base + (bank % banks) * 0x8000 + usize::from(address & 0x7FFF);
        self.prg.get(offset).copied().unwrap_or(0)
    }
}

impl Mapper for Bmc301 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let o = self.latch_data & 0x80 != 0;
        if o {
            if self.latch_data & 0x01 != 0 {
                // NROM-256: one 32 KiB bank over the whole window.
                self.read_bank32(self.inner_bank() >> 1, address)
            } else {
                // NROM-128: the 16 KiB bank mirrored over both windows.
                self.read_bank(self.inner_bank(), address)
            }
        } else if address < 0xC000 {
            self.read_bank(self.inner_bank(), address)
        } else {
            // L selects fixed inner bank 0 or 7.
            let fixed = if self.latch_addr & 0x0200 != 0 { 7 } else { 0 };
            self.read_bank(fixed, address)
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.latch_addr = address & 0x0700;
            self.latch_data = value;
            self.mirroring = if value & 0x02 != 0 {
                Mirroring::Horizontal
            } else {
                Mirroring::Vertical
            };
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        301
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000
    }
}

/// Simple discrete BMC multicarts (mappers 104 and 290): a 32 KiB PRG
/// window with an 8 KiB fixed CHR window and board-specific latch decodes.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct DiscreteBmc {
    prg: Vec<u8>,
    chr: Vec<u8>,
    board: u16,
    reg0: u8,
    reg1: u8,
    last_addr: u16,
    mirroring: Mirroring,
}

impl DiscreteBmc {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header, board: u16) -> Self {
        Self {
            prg,
            chr,
            board,
            reg0: 0,
            reg1: 0,
            last_addr: 0,
            mirroring: header.mirroring,
        }
    }

    fn prg_16k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_32k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x8000).max(1);
        self.prg
            .get((bank % banks) * 0x8000 + usize::from(address & 0x7FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for DiscreteBmc {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        match self.board {
            104 => {
                if address < 0xC000 {
                    self.prg_16k(usize::from(self.reg0), address)
                } else {
                    self.prg_16k(usize::from((self.reg1 & 0x70) | 0x0F), address)
                }
            }
            290 => {
                if self.last_addr & 0x80 != 0 {
                    self.prg_16k(usize::from(self.reg0), address)
                } else {
                    self.prg_32k(usize::from(self.reg0 >> 1), address)
                }
            }
            301 => {
                let a = self.last_addr;
                let inner = usize::from((a >> 2) & 0x07);
                let outer128 = usize::from((a >> 5) & 0x03);
                let outer256 = usize::from((a >> 7) & 0x01);
                let outer512 = usize::from((a >> 8) & 0x01);
                let bank = (outer512 << 6) | (outer256 << 5) | (outer128 << 3) | inner;
                self.prg_16k(bank, address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match self.board {
            104 => {
                if address >= 0xC000 {
                    self.reg0 = (self.reg0 & 0xF0) | (value & 0x0F);
                } else if (0x8000..=0x9FFF).contains(&address) && value & 0x08 != 0 {
                    self.reg0 = (self.reg0 & 0x0F) | ((value << 4) & 0x70);
                    self.reg1 = value;
                }
            }
            290 => {
                if address >= 0x8000 {
                    let prg = ((address >> 10) & 0x1E) as u8;
                    let chr = (((address & 0x0300) >> 5) | (address & 0x07)) as u8;
                    self.reg0 = if address & 0x80 != 0 {
                        prg | ((address >> 6) & 1) as u8
                    } else {
                        prg & 0xFE
                    };
                    self.reg1 = chr;
                    self.mirroring = if address & 0x400 != 0 {
                        Mirroring::Horizontal
                    } else {
                        Mirroring::Vertical
                    };
                    self.last_addr = address;
                }
            }
            301 if address >= 0x8000 => {
                self.last_addr = address;
                self.mirroring = if address & 0x02 != 0 {
                    Mirroring::Horizontal
                } else {
                    Mirroring::Vertical
                };
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = match self.board {
            290 | 301 if false => usize::from(self.reg1) % banks,
            _ => 0,
        };
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = match self.board {
            290 | 301 if false => usize::from(self.reg1) % banks,
            _ => 0,
        };
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        self.board
    }
}

/// Irem H3001 (mapper 65): 8 KiB PRG banking, eight 1 KiB CHR banks and a
/// CPU-cycle down-counter.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Irem65 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    /// Outer PRG bank base and inner mask applied by the 446 supervisor.
    outer: usize,
    outer_mask: usize,
    prg_reg0: u8,
    prg_reg1: u8,
    prg_layout: bool,
    chr_regs: [u8; 8],
    mirroring: Mirroring,
    irq_reload: u16,
    irq_counter: u16,
    irq_enabled: bool,
    irq_pending: bool,
}

impl Irem65 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            outer: 0,
            outer_mask: 0xFF,
            prg_reg0: 0,
            prg_reg1: 1,
            prg_layout: false,
            chr_regs: [0; 8],
            mirroring: header.mirroring,
            irq_reload: 0,
            irq_counter: 0,
            irq_enabled: false,
            irq_pending: false,
        }
    }

    /// Builds an H3001 whose bank registers are offset and masked by the
    /// mapper-446 supervisor's `$5001`/`$5003` values.
    fn new_windowed(
        prg: Vec<u8>,
        chr: Vec<u8>,
        header: Header,
        outer: usize,
        outer_mask: usize,
    ) -> Self {
        let mut this = Self::new(prg, chr, header);
        this.outer = outer;
        this.outer_mask = outer_mask;
        this
    }

    fn prg_offset(&self, address: u16) -> usize {
        let total = (self.prg.len() / 0x2000).max(1);
        // H3001 fixes the last two 8 KiB banks. For the <=512 KiB boards this
        // is 0x3F/0x3E; larger images (the 446 supervisor passes 1 MiB) need
        // the true end of the image.
        let fixed_last = total - 1;
        let fixed_second = total.saturating_sub(2);
        let bank = match (address & 0xE000, self.prg_layout) {
            (0x8000, false) => usize::from(self.prg_reg0),
            (0x8000, true) => fixed_second,
            (0xA000, _) => usize::from(self.prg_reg1),
            (0xC000, false) => fixed_second,
            (0xC000, true) => usize::from(self.prg_reg0),
            (0xE000, _) => fixed_last,
            _ => 0,
        };
        let bank = (bank & self.outer_mask) | self.outer;
        bank % total * 0x2000 + usize::from(address & 0x1FFF)
    }
}

impl Mapper for Irem65 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        self.prg.get(self.prg_offset(address)).copied().unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x8000..=0x8FFF => self.prg_reg0 = value,
            0x9000..=0x9FFF => match address & 0x0007 {
                0 => self.prg_layout = value & 0x80 != 0,
                1 => {
                    self.mirroring = match (value >> 6) & 0x03 {
                        0 => Mirroring::Vertical,
                        2 => Mirroring::Horizontal,
                        _ => Mirroring::SingleLower,
                    }
                }
                3 => {
                    self.irq_enabled = value & 0x80 != 0;
                    self.irq_pending = false;
                }
                4 => {
                    self.irq_counter = self.irq_reload;
                    self.irq_pending = false;
                }
                5 => self.irq_reload = (self.irq_reload & 0x00FF) | (u16::from(value) << 8),
                6 => self.irq_reload = (self.irq_reload & 0xFF00) | u16::from(value),
                _ => {}
            },
            0xA000..=0xAFFF => self.prg_reg1 = value,
            0xB000..=0xBFFF => self.chr_regs[usize::from(address & 0x0007)] = value,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from((address >> 10) & 0x07);
        let bank = usize::from(self.chr_regs[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from((address >> 10) & 0x07);
        let bank = usize::from(self.chr_regs[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        65
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xB000..=0xBFFF).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled || self.irq_counter == 0 {
            return;
        }
        self.irq_counter -= 1;
        if self.irq_counter == 0 {
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Sunsoft-3 (mapper 67): 16 KiB PRG banking, four 2 KiB CHR banks and a
/// write-twice CPU-cycle counter.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Sunsoft3 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_bank: u8,
    chr_banks: [u8; 4],
    mirroring: Mirroring,
    irq_counter: u16,
    irq_enabled: bool,
    irq_pending: bool,
    irq_low_next: bool,
}

impl Sunsoft3 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            prg_bank: 0,
            chr_banks: [0; 4],
            mirroring: header.mirroring,
            irq_counter: 0,
            irq_enabled: false,
            irq_pending: false,
            irq_low_next: false,
        }
    }
}

impl Mapper for Sunsoft3 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let bank = if address < 0xC000 {
            usize::from(self.prg_bank) % banks
        } else {
            banks - 1
        };
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0xF800 {
            0x8000 => self.irq_pending = false,
            0x8800 => self.chr_banks[0] = value,
            0x9800 => self.chr_banks[1] = value,
            0xA800 => self.chr_banks[2] = value,
            0xB800 => self.chr_banks[3] = value,
            0xC800 => {
                if self.irq_low_next {
                    self.irq_counter = (self.irq_counter & 0xFF00) | u16::from(value);
                } else {
                    self.irq_counter = (self.irq_counter & 0x00FF) | (u16::from(value) << 8);
                }
                self.irq_low_next = !self.irq_low_next;
            }
            0xD800 => {
                self.irq_enabled = value & 0x10 != 0;
                self.irq_low_next = false;
            }
            0xE800 => {
                self.mirroring = match value & 0x03 {
                    0 => Mirroring::Vertical,
                    1 => Mirroring::Horizontal,
                    2 => Mirroring::SingleLower,
                    _ => Mirroring::SingleUpper,
                };
            }
            0xF800 => self.prg_bank = value & 0x0F,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        self.chr
            .get(bank * 0x800 + usize::from(address & 0x7FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x800 + usize::from(address & 0x7FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        67
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        matches!(address & 0xF800, 0x8800 | 0x9800 | 0xA800 | 0xB800)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled {
            return;
        }
        if self.irq_counter == 0 {
            self.irq_counter = 0xFFFF;
            self.irq_pending = true;
            self.irq_enabled = false;
        } else {
            self.irq_counter -= 1;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// INL (mapper 31): eight independent 4 KiB PRG slots written at `$5FF8-$5FFF`,
/// with 8 KiB of flat CHR-RAM.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Inl31 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    slots: [u8; 8],
    mirroring: Mirroring,
}

impl Inl31 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        // Slot 7 powers on at the last 4 KiB bank so the reset vector is
        // reachable; the other slots start at bank 0.
        let mut slots = [0u8; 8];
        slots[7] = ((prg.len() / 0x1000).max(1) - 1) as u8;
        Self {
            prg,
            chr,
            slots,
            mirroring: header.mirroring,
        }
    }
}

impl Mapper for Inl31 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x1000).max(1);
        let slot = usize::from((address >> 12) & 0x07);
        let bank = usize::from(self.slots[slot]) % banks;
        self.prg
            .get(bank * 0x1000 + usize::from(address & 0x0FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if (0x5FF8..=0x5FFF).contains(&address) {
            self.slots[usize::from(address & 0x07)] = value;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        31
    }
}

/// Jaleco JF-17 (mapper 72): bus-conflicted PRG/CHR latches with a strobe.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Jaleco72 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_bank: u8,
    chr_bank: u8,
    prg_strobe: bool,
    chr_strobe: bool,
    mirroring: Mirroring,
    number: u16,
    prg_mask: u8,
    /// JF-19 (mapper 92) keeps the first bank fixed and switches the second;
    /// JF-17 (mapper 72) does the opposite.
    switchable_high: bool,
}

impl Jaleco72 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self::new_variant(prg, chr, header, 72, 0x0F, false)
    }

    fn new_variant(
        prg: Vec<u8>,
        chr: Vec<u8>,
        header: Header,
        number: u16,
        prg_mask: u8,
        switchable_high: bool,
    ) -> Self {
        Self {
            prg,
            chr,
            prg_bank: 0,
            chr_bank: 0,
            prg_strobe: false,
            chr_strobe: false,
            mirroring: header.mirroring,
            number,
            prg_mask,
            switchable_high,
        }
    }
}

impl Mapper for Jaleco72 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let bank = match (self.switchable_high, address < 0xC000) {
            (false, true) => usize::from(self.prg_bank) % banks,
            (false, false) => banks - 1,
            (true, true) => 0,
            (true, false) => usize::from(self.prg_bank) % banks,
        };
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            let effective = value & self.prg_read(address);
            let prg_strobe = effective & 0x80 != 0;
            let chr_strobe = effective & 0x40 != 0;
            if prg_strobe && !self.prg_strobe {
                self.prg_bank = effective & self.prg_mask;
            }
            if chr_strobe && !self.chr_strobe {
                self.chr_bank = effective & 0x0F;
            }
            self.prg_strobe = prg_strobe;
            self.chr_strobe = chr_strobe;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        self.number
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000
    }
}

/// Irem/Jaleco (mapper 78): UxROM-like banking with a mirroring bit whose
/// wiring depends on the board variant.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Irem78 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_bank: u8,
    chr_bank: u8,
    mirroring: Mirroring,
    holy_diver: bool,
}

impl Irem78 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        let holy_diver = match (header.nes2, header.submapper) {
            (true, 1) => false,
            (true, 3) => true,
            _ => header.four_screen,
        };
        Self {
            prg,
            chr,
            prg_bank: 0,
            chr_bank: 0,
            mirroring: if holy_diver {
                Mirroring::Horizontal
            } else {
                Mirroring::SingleLower
            },
            holy_diver,
        }
    }
}

impl Mapper for Irem78 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let bank = if address < 0xC000 {
            usize::from(self.prg_bank) % banks
        } else {
            banks - 1
        };
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.prg_bank = value & 0x07;
            self.chr_bank = (value >> 4) & 0x0F;
            let mbit = value & 0x08 != 0;
            self.mirroring = if self.holy_diver {
                if mbit {
                    Mirroring::Vertical
                } else {
                    Mirroring::Horizontal
                }
            } else if mbit {
                Mirroring::SingleUpper
            } else {
                Mirroring::SingleLower
            };
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        78
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000
    }
}

/// Racermate Challenge II (mapper 168): switchable 16 KiB PRG and 4 KiB CHR
/// pages with a free-running CPU-cycle IRQ that fires every 1024 cycles.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Racermate168 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_bank: u8,
    mirroring: Mirroring,
    irq_counter: u16,
    irq_pending: bool,
}

impl Racermate168 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            prg_bank: 0,
            mirroring: header.mirroring,
            irq_counter: 0,
            irq_pending: false,
        }
    }
}

impl Mapper for Racermate168 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let bank = if address < 0xC000 {
            usize::from(self.prg_bank) % banks
        } else {
            banks - 1
        };
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0xC000 {
            0x8000 => self.prg_bank = (value >> 6) & 0x03,
            0xC000 => {
                self.irq_counter = 1024;
                self.irq_pending = false;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address) & 0x1FFF)
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address) & 0x1FFF) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        168
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        self.irq_counter = self.irq_counter.wrapping_sub(1);
        if self.irq_counter == 0 {
            self.irq_counter = 1024;
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// UNL-Mapper-117: four switchable 8 KiB PRG pages, eight 1 KiB CHR pages,
/// an A12-rise IRQ with a reload/enable pair, and `$D000` mirroring.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Unl117 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 4],
    chr_banks: [u8; 8],
    mirroring: Mirroring,
    irq_reload: u8,
    irq_counter: u8,
    irq_enabled: bool,
    irq_alt: bool,
    irq_pending: bool,
}

impl Unl117 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        let banks = (prg.len() / 0x2000).max(1) as u8;
        let last = |offset: u8| banks.saturating_sub(offset);
        Self {
            prg,
            chr,
            prg_banks: [last(4), last(3), last(2), last(1)],
            chr_banks: [0; 8],
            mirroring: header.mirroring,
            irq_reload: 0,
            irq_counter: 0,
            irq_enabled: false,
            irq_alt: false,
            irq_pending: false,
        }
    }
}

impl Mapper for Unl117 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x2000).max(1);
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = usize::from(self.prg_banks[slot]) % banks;
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x8000..=0x8003 => self.prg_banks[usize::from(address & 0x03)] = value,
            0xA000..=0xA007 => self.chr_banks[usize::from(address & 0x07)] = value,
            0xC001 => self.irq_reload = value,
            0xC002 => {
                self.irq_pending = false;
                self.irq_alt = false;
            }
            0xC003 => {
                self.irq_counter = self.irq_reload;
                self.irq_alt = true;
            }
            0xD000 => {
                self.mirroring = if value & 0x01 != 0 {
                    Mirroring::Horizontal
                } else {
                    Mirroring::Vertical
                }
            }
            0xE000 => {
                self.irq_enabled = value & 0x01 != 0;
                self.irq_pending = false;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from((address >> 10) & 0x07);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x400).max(1);
        let slot = usize::from((address >> 10) & 0x07);
        let bank = usize::from(self.chr_banks[slot]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        117
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xA000..=0xA007).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_scanline(&mut self) {
        if self.irq_enabled && self.irq_alt && self.irq_counter != 0 {
            self.irq_counter -= 1;
            if self.irq_counter == 0 {
                self.irq_pending = true;
                self.irq_alt = false;
            }
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Yoko (mapper 264): PRG/CHR paging modes selected by `$8400`, DIP/extra
/// registers in `$5000-$5FFF`, and a CPU-cycle down-counter.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Yoko264 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    regs: [u8; 7],
    ex: [u8; 4],
    mode: u8,
    bank: u8,
    mirroring: Mirroring,
    irq_counter: u16,
    irq_enabled: bool,
    irq_pending: bool,
}

impl Yoko264 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            regs: [0; 7],
            ex: [0; 4],
            mode: 0,
            bank: 0,
            mirroring: header.mirroring,
            irq_counter: 0,
            irq_enabled: false,
            irq_pending: false,
        }
    }

    fn prg_bank(&self, slot: usize) -> usize {
        let banks = (self.prg.len() / 0x2000).max(1);
        let page = if self.mode & 0x10 != 0 {
            let outer = usize::from(self.bank & 0x08) << 1;
            if slot == 3 {
                outer | 0x0F
            } else {
                outer | usize::from(self.regs[slot] & 0x0F)
            }
        } else if self.mode & 0x08 != 0 {
            (usize::from(self.bank & 0xFE) << 1) + slot
        } else if slot < 2 {
            (usize::from(self.bank) << 1) + slot
        } else {
            banks.saturating_sub(2) + (slot - 2)
        };
        page % banks
    }
}

impl Mapper for Yoko264 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x2000).max(1);
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = self.prg_bank(slot) % banks;
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn read_io(&mut self, address: u16) -> u8 {
        if (0x5000..=0x5FFF).contains(&address) {
            if address <= 0x53FF {
                // Two DIP switches, both off by default.
                return 0;
            }
            return self.ex[usize::from(address & 0x03)];
        }
        self.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address < 0x5000 {
            return;
        }
        if address < 0x8000 {
            self.ex[usize::from(address & 0x03)] = value;
            return;
        }
        match address & 0x8C17 {
            0x8000 => {
                self.bank = value;
                self.mirroring = if self.mode & 0x01 != 0 {
                    Mirroring::Horizontal
                } else {
                    Mirroring::Vertical
                };
            }
            0x8400 => {
                self.mode = value;
                self.mirroring = if self.mode & 0x01 != 0 {
                    Mirroring::Horizontal
                } else {
                    Mirroring::Vertical
                };
            }
            0x8800 => {
                self.irq_counter = (self.irq_counter & 0xFF00) | u16::from(value);
                self.irq_pending = false;
            }
            0x8801 => {
                self.irq_enabled = self.mode & 0x80 != 0;
                self.irq_counter = (self.irq_counter & 0x00FF) | (u16::from(value) << 8);
            }
            0x8C00..=0x8C02 => {
                self.regs[usize::from((address & 0x8C17) - 0x8C00)] = value;
            }
            0x8C10 | 0x8C11 => {
                self.regs[usize::from((address & 0x8C17) - 0x8C10) + 3] = value;
            }
            0x8C16 | 0x8C17 => {
                self.regs[usize::from((address & 0x8C17) - 0x8C16) + 5] = value;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = usize::from(self.regs[slot + 3]) % banks;
        self.chr
            .get(bank * 0x800 + usize::from(address & 0x7FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = usize::from(self.regs[slot + 3]) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x800 + usize::from(address & 0x7FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        264
    }

    fn low_window(&self) -> Option<(u16, u16)> {
        Some((0x5000, 0x5FFF))
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        matches!(address & 0x8C17, 0x8C10 | 0x8C11 | 0x8C16 | 0x8C17)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled {
            return;
        }
        self.irq_counter = self.irq_counter.wrapping_sub(1);
        if self.irq_counter == 0 {
            self.irq_enabled = false;
            self.irq_counter = 0xFFFF;
            self.irq_pending = true;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_pending = false;
    }
}

/// Super 40-in-1 WS (mapper 332): a locked register pair in `$6000-$6FFF`
/// selects two 16 KiB PRG banks, an 8 KiB CHR bank and mirroring.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Multicart332 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 2],
    chr_bank: u8,
    mirroring: Mirroring,
    locked: bool,
}

impl Multicart332 {
    fn new(prg: Vec<u8>, chr: Vec<u8>) -> Self {
        Self {
            prg,
            chr,
            prg_banks: [0, 1],
            chr_bank: 0,
            mirroring: Mirroring::Vertical,
            locked: false,
        }
    }
}

impl Mapper for Multicart332 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let slot = usize::from(address >= 0xC000);
        let bank = usize::from(self.prg_banks[slot]) % banks;
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if (0x6000..=0x6FFF).contains(&address) && !self.locked {
            if address & 0x01 != 0 {
                self.chr_bank = value;
            } else {
                self.locked = value & 0x20 == 0x20;
                let low = value & !((!value >> 3) & 0x01);
                let high = value | ((!value >> 3) & 0x01);
                self.prg_banks = [low, high];
                self.mirroring = if value & 0x10 != 0 {
                    Mirroring::Horizontal
                } else {
                    Mirroring::Vertical
                };
            }
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address) & 0x1FFF) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        332
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x6000..=0x6FFF).contains(&address)
    }
}

/// Taito X1-017 (mapper 552): 8 KiB PRG pages with a scrambled register,
/// six 1 KiB CHR registers with a 2 KiB/1 KiB mode, and save-RAM permission
/// bytes.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Taito552 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 3],
    chr_regs: [u8; 6],
    chr_mode: bool,
    mirroring: Mirroring,
    ram_permission: [u8; 3],
    ram: Vec<u8>,
}

impl Taito552 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            prg_banks: [0, 1, 2],
            chr_regs: [0; 6],
            chr_mode: false,
            mirroring: header.mirroring,
            ram_permission: [0; 3],
            ram: vec![0; 0x1400],
        }
    }

    fn chr_bank(&self, slot: usize) -> usize {
        let banks = (self.chr.len() / 0x400).max(1);
        let raw = if self.chr_mode {
            match slot {
                0 => usize::from(self.chr_regs[2]),
                1 => usize::from(self.chr_regs[3]),
                2 => usize::from(self.chr_regs[4]),
                3 => usize::from(self.chr_regs[5]),
                4 | 5 => usize::from(self.chr_regs[0] & 0xFE) + (slot & 1),
                _ => usize::from(self.chr_regs[1] & 0xFE) + (slot & 1),
            }
        } else {
            match slot {
                0 | 1 => usize::from(self.chr_regs[0] & 0xFE) + (slot & 1),
                2 | 3 => usize::from(self.chr_regs[1] & 0xFE) + (slot & 1),
                4 => usize::from(self.chr_regs[2]),
                5 => usize::from(self.chr_regs[3]),
                6 => usize::from(self.chr_regs[4]),
                _ => usize::from(self.chr_regs[5]),
            }
        };
        raw % banks
    }
}

impl Mapper for Taito552 {
    fn prg_read(&self, address: u16) -> u8 {
        if (0x6000..=0x73FF).contains(&address) {
            return self.ram[usize::from(address - 0x6000)];
        }
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x2000).max(1);
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = if slot == 3 {
            banks - 1
        } else {
            usize::from(self.prg_banks[slot]) % banks
        };
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if (0x6000..=0x73FF).contains(&address) {
            self.ram[usize::from(address - 0x6000)] = value;
            return;
        }
        match address {
            0x7EF0..=0x7EF5 => self.chr_regs[usize::from(address & 0x0F)] = value,
            0x7EF6 => {
                self.mirroring = if value & 0x01 != 0 {
                    Mirroring::Vertical
                } else {
                    Mirroring::Horizontal
                };
                self.chr_mode = value & 0x02 != 0;
            }
            0x7EF7..=0x7EF9 => self.ram_permission[usize::from((address & 0x0F) - 7)] = value,
            0x7EFA..=0x7EFC => {
                let page = ((value & 0x20) >> 5)
                    | ((value & 0x10) >> 3)
                    | ((value & 0x08) >> 1)
                    | ((value & 0x04) << 1)
                    | ((value & 0x02) << 3)
                    | ((value & 0x01) << 5);
                self.prg_banks[usize::from(address - 0x7EFA)] = page;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from((address >> 10) & 0x07);
        let bank = self.chr_bank(slot);
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from((address >> 10) & 0x07);
        let bank = self.chr_bank(slot);
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        552
    }

    fn prg_ram(&self) -> &[u8] {
        &self.ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        matches!(address, 0x7EF0..=0x7EF6)
    }
}

/// Reset-TXROM multicarts (mapper 313): MMC3 banking with a 2-bit outer bank
/// that advances on every soft reset.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Mmc3_313 {
    inner: Mmc3,
    counter: u8,
}

impl Mmc3_313 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            inner: Mmc3::new_as(prg, chr, header, 313),
            counter: 0,
        }
    }

    fn prg_bank(&self, slot: usize) -> usize {
        let banks = self.inner.prg_banks();
        let page = (usize::from(self.counter) << 4) | (self.inner.prg_slot(slot) & 0x0F);
        page % banks
    }

    fn chr_bank(&self, slot: usize) -> usize {
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let page = (usize::from(self.counter) << 7) | (self.inner.chr_bank(slot) & 0x7F);
        page % banks
    }
}

impl Mapper for Mmc3_313 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return self.inner.prg_read(address);
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = self.prg_bank(slot);
        self.inner.prg[bank * 0x2000 + usize::from(address & 0x1FFF)]
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        self.inner.prg_write(address, value);
    }

    fn chr_read(&self, address: u16) -> u8 {
        let slot = usize::from(address) / 0x400;
        let bank = self.chr_bank(slot);
        let banks = (self.inner.chr.len() / 0x400).max(1);
        self.inner.chr[bank % banks * 0x400 + usize::from(address & 0x3FF)]
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let slot = usize::from(address) / 0x400;
        let bank = self.chr_bank(slot);
        let banks = (self.inner.chr.len() / 0x400).max(1);
        let index = bank % banks * 0x400 + usize::from(address & 0x3FF);
        if let Some(byte) = self.inner.chr.get_mut(index) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.inner.mirroring()
    }

    fn number(&self) -> u16 {
        313
    }

    fn prg_ram(&self) -> &[u8] {
        &self.inner.prg_ram
    }

    fn soft_reset(&mut self) {
        self.counter = (self.counter + 1) & 0x03;
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x8000..=0x9FFF).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.inner.irq_line()
    }

    fn clock_scanline(&mut self) {
        self.inner.clock_scanline();
    }

    fn acknowledge_irq(&mut self) {
        self.inner.acknowledge_irq();
    }
}

/// T230 (mapper 529): VRC-style 8 KiB PRG / 1 KiB CHR banking with an outer
/// CHR-RAM bank and the VRC CPU-cycle IRQ.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct T230 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_reg0: u8,
    prg_reg1: u8,
    prg_mode: bool,
    outer: usize,
    lo_chr: [u8; 8],
    hi_chr: [u8; 8],
    chr_is_ram: bool,
    mirroring: Mirroring,
    irq_reload: u8,
    irq_counter: u8,
    irq_prescaler: i32,
    irq_enabled: bool,
    irq_after_ack: bool,
    irq_cycle_mode: bool,
    irq_pending: bool,
}

impl T230 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            prg_reg0: 0,
            prg_reg1: 0,
            prg_mode: false,
            outer: 0,
            lo_chr: [0; 8],
            hi_chr: [0; 8],
            chr_is_ram: header.chr_size == 0,
            mirroring: header.mirroring,
            irq_reload: 0,
            irq_counter: 0,
            irq_prescaler: 0,
            irq_enabled: false,
            irq_after_ack: false,
            irq_cycle_mode: false,
            irq_pending: false,
        }
    }

    fn prg_bank(&self, slot: usize) -> usize {
        let banks = (self.prg.len() / 0x2000).max(1);
        let fixed = 0x1E | self.outer;
        let page = match (self.prg_mode, slot) {
            (false, 0) => usize::from(self.prg_reg0) | self.outer,
            (false, 2) => fixed,
            (true, 0) => fixed,
            (true, 2) => usize::from(self.prg_reg0) | self.outer,
            (_, 1) => usize::from(self.prg_reg1),
            _ => banks - 1,
        };
        page % banks
    }

    fn chr_bank(&self, slot: usize) -> usize {
        let banks = (self.chr.len() / 0x400).max(1);
        let page = usize::from(self.lo_chr[slot]) | (usize::from(self.hi_chr[slot]) << 4);
        page % banks
    }
}

impl Mapper for T230 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let slot = usize::from((address - 0x8000) / 0x2000);
        let bank = self.prg_bank(slot);
        self.prg
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        let reduced = (address & 0xF000)
            | (if address & 0x2A != 0 { 0x02 } else { 0 })
            | (if address & 0x15 != 0 { 0x01 } else { 0 });
        match reduced {
            0x9000 | 0x9001 => {
                self.mirroring = match value & 0x03 {
                    0 => Mirroring::Vertical,
                    1 => Mirroring::Horizontal,
                    2 => Mirroring::SingleLower,
                    _ => Mirroring::SingleUpper,
                };
            }
            0x9002 | 0x9003 => self.prg_mode = value & 0x02 != 0,
            0xA000..=0xA003 => {
                self.prg_reg0 = (value & 0x1F) << 1;
                self.prg_reg1 = self.prg_reg0 | 0x01;
            }
            0xB000..=0xE003 => {
                if self.chr_is_ram {
                    self.outer = usize::from((value & 0x08) << 2);
                } else {
                    let page = usize::from((reduced >> 12) & 0x07);
                    let reg = ((page - 3) << 1) | usize::from((reduced >> 1) & 1);
                    if reduced & 1 == 0 {
                        self.lo_chr[reg] = value & 0x0F;
                    } else {
                        self.hi_chr[reg] = value & 0x1F;
                    }
                }
            }
            0xF000 => self.irq_reload = (self.irq_reload & 0xF0) | (value & 0x0F),
            0xF001 => self.irq_reload = (self.irq_reload & 0x0F) | ((value & 0x0F) << 4),
            0xF002 => {
                self.irq_after_ack = value & 0x01 != 0;
                self.irq_enabled = value & 0x02 != 0;
                self.irq_cycle_mode = value & 0x04 != 0;
                if self.irq_enabled {
                    self.irq_counter = self.irq_reload;
                    self.irq_prescaler = 341;
                }
                self.irq_pending = false;
            }
            0xF003 => {
                self.irq_enabled = self.irq_after_ack;
                self.irq_pending = false;
            }
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        if self.chr_is_ram {
            return self
                .chr
                .get(usize::from(address & 0x1FFF))
                .copied()
                .unwrap_or(0);
        }
        let slot = usize::from((address >> 10) & 0x07);
        let bank = self.chr_bank(slot);
        self.chr
            .get(bank * 0x400 + usize::from(address & 0x3FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if self.chr_is_ram {
            if let Some(byte) = self.chr.get_mut(usize::from(address & 0x1FFF)) {
                *byte = value;
            }
            return;
        }
        let slot = usize::from((address >> 10) & 0x07);
        let bank = self.chr_bank(slot);
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x400 + usize::from(address & 0x3FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        529
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0xB000..=0xE003).contains(&address)
    }

    fn irq_line(&self) -> bool {
        self.irq_pending
    }

    fn clock_cpu(&mut self) {
        if !self.irq_enabled {
            return;
        }
        self.irq_prescaler -= 3;
        if self.irq_cycle_mode || self.irq_prescaler <= 0 {
            if self.irq_counter == 0xFF {
                self.irq_counter = self.irq_reload;
                self.irq_pending = true;
            } else {
                self.irq_counter += 1;
            }
            self.irq_prescaler += 341;
        }
    }

    fn acknowledge_irq(&mut self) {
        self.irq_enabled = self.irq_after_ack;
        self.irq_pending = false;
    }
}

/// Eh8813A (mapper 519): address-decoded 16 KiB PRG / 8 KiB CHR banking with
/// the DIP-altered register readback.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Eh8813A {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_banks: [u8; 2],
    chr_bank: u8,
    mirroring: Mirroring,
    alter_read: bool,
}

impl Eh8813A {
    fn new(prg: Vec<u8>, chr: Vec<u8>, _header: Header) -> Self {
        let mut mapper = Self {
            prg,
            chr,
            prg_banks: [0, 1],
            chr_bank: 0,
            mirroring: Mirroring::Vertical,
            alter_read: false,
        };
        // Power-on reset performs the same write as `Reset` in the reference.
        mapper.write_register(0x8000, 0);
        mapper.alter_read = false;
        mapper
    }

    fn write_register(&mut self, address: u16, value: u8) {
        if address & 0x0100 != 0 {
            return;
        }
        self.alter_read = address & 0x40 != 0;
        if address & 0x80 != 0 {
            let bank = (address & 0x07) as u8;
            self.prg_banks = [bank, bank];
        } else {
            let base = (address & 0x06) as u8;
            self.prg_banks = [base, base + 1];
        }
        self.chr_bank = value & 0x0F;
    }
}

impl Mapper for Eh8813A {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x4000).max(1);
        let slot = usize::from(address >= 0xC000);
        let bank = usize::from(self.prg_banks[slot]) % banks;
        self.prg
            .get(bank * 0x4000 + usize::from(address & 0x3FFF))
            .copied()
            .unwrap_or(0)
    }

    fn read_io(&mut self, address: u16) -> u8 {
        let address = if self.alter_read {
            address & 0xFFF0
        } else {
            address
        };
        self.prg_read(address)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address >= 0x8000 {
            self.write_register(address, value);
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        self.chr
            .get(bank * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank = usize::from(self.chr_bank) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        519
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000 && address & 0x0100 == 0
    }
}

/// BMC GK 6-in-1 (mapper 57): two address-decoded registers select a
/// 16/32 KiB PRG window and an 8 KiB CHR bank.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Bmc57 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    reg0: u8,
    reg1: u8,
    mirroring: Mirroring,
}

impl Bmc57 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            reg0: 0,
            reg1: 0,
            mirroring: header.mirroring,
        }
    }
}

impl Mapper for Bmc57 {
    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let len = self.prg.len().max(1);
        let index = if self.reg1 & 0x10 != 0 {
            let bank = usize::from((self.reg1 >> 5) & 0x06) >> 1;
            bank * 0x8000 + usize::from(address & 0x7FFF)
        } else {
            let bank = usize::from((self.reg1 >> 5) & 0x07);
            bank * 0x4000 + usize::from(address & 0x3FFF)
        };
        self.prg.get(index % len).copied().unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address & 0x8800 {
            0x8000 => self.reg0 = value,
            0x8800 => self.reg1 = value,
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank =
            usize::from((self.reg0 & 0x40) >> 3) | usize::from((self.reg0 | self.reg1) & 0x07);
        self.chr
            .get(bank % banks * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x2000).max(1);
        let bank =
            usize::from((self.reg0 & 0x40) >> 3) | usize::from((self.reg0 | self.reg1) & 0x07);
        if let Some(byte) = self
            .chr
            .get_mut(bank % banks * 0x2000 + usize::from(address & 0x1FFF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        57
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        (0x8000..=0xFFFF).contains(&address)
    }
}

/// K-1029 / 100-in-1 Contra Function 16 (mapper 15): four PRG window modes,
/// CHR-RAM and 8 KiB of PRG-RAM at `$6000`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Multicart15 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    prg_ram: Vec<u8>,
    mode: u8,
    prg_bank: u8,
    half: u8,
    horizontal: bool,
}

impl Multicart15 {
    fn new(prg: Vec<u8>, chr: Vec<u8>) -> Self {
        Self {
            prg,
            chr,
            prg_ram: vec![0; 0x2000],
            mode: 0,
            prg_bank: 0,
            half: 0,
            horizontal: false,
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get(bank % banks * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_16k(&self, bank: usize, offset: usize) -> u8 {
        let banks = (self.prg.len() / 0x4000).max(1);
        self.prg
            .get((bank % banks) * 0x4000 + offset)
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for Multicart15 {
    fn prg_read(&self, address: u16) -> u8 {
        if (0x6000..=0x7FFF).contains(&address) {
            return self.prg_ram[usize::from(address - 0x6000)];
        }
        if address < 0x8000 {
            return 0;
        }
        let win = usize::from(address - 0x8000);
        let bank = usize::from(self.prg_bank);
        match self.mode {
            0 => {
                if win < 0x4000 {
                    self.prg_16k(bank, win)
                } else {
                    self.prg_16k(bank | 1, win - 0x4000)
                }
            }
            1 => {
                if win < 0x4000 {
                    self.prg_16k(bank, win)
                } else {
                    self.prg_16k(bank | 7, win - 0x4000)
                }
            }
            2 => self.prg_8k((bank << 1) | usize::from(self.half), address),
            _ => self.prg_16k(bank, win & 0x3FFF),
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if (0x6000..=0x7FFF).contains(&address) {
            self.prg_ram[usize::from(address - 0x6000)] = value;
            return;
        }
        if address >= 0x8000 {
            self.mode = (address & 0x03) as u8;
            self.horizontal = value & 0x40 != 0;
            self.prg_bank = value & 0x3F;
            self.half = u8::from(value & 0x80 != 0);
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address) & 0x1FFF)
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address) & 0x1FFF) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        if self.horizontal {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        }
    }

    fn number(&self) -> u16 {
        15
    }

    fn prg_ram(&self) -> &[u8] {
        &self.prg_ram
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address >= 0x8000
    }
}

/// FDS-conversion protection board (mapper 120): a switchable 8 KiB PRG bank
/// at `$6000` and the last four 8 KiB banks fixed at `$8000`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct FdsConv120 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    reg0: u8,
    mirroring: Mirroring,
    /// Presence-only marker so the bus routes `$6000-$7FFF` reads to the
    /// mapper (the window is PRG-ROM, not RAM).
    routing: Vec<u8>,
}

impl FdsConv120 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            reg0: 0,
            mirroring: header.mirroring,
            routing: vec![0],
        }
    }

    fn prg_8k(&self, bank: usize, address: u16) -> u8 {
        let banks = (self.prg.len() / 0x2000).max(1);
        self.prg
            .get(bank % banks * 0x2000 + usize::from(address & 0x1FFF))
            .copied()
            .unwrap_or(0)
    }
}

impl Mapper for FdsConv120 {
    fn prg_read(&self, address: u16) -> u8 {
        match address {
            0x6000..=0x7FFF => self.prg_8k(usize::from(self.reg0), address),
            0x8000..=0xFFFF => {
                let banks = (self.prg.len() / 0x2000).max(1);
                let base = banks.saturating_sub(4);
                let slot = usize::from((address - 0x8000) / 0x2000);
                self.prg_8k(base + slot, address)
            }
            _ => 0,
        }
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        if address == 0x41FF {
            self.reg0 = value;
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        self.chr
            .get(usize::from(address) & 0x1FFF)
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        if let Some(byte) = self.chr.get_mut(usize::from(address) & 0x1FFF) {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        self.mirroring
    }

    fn number(&self) -> u16 {
        120
    }

    fn prg_ram(&self) -> &[u8] {
        &self.routing
    }
}

/// Sachen 8259 variant (mapper 137): 32 KiB PRG bank, four 2 KiB CHR banks
/// plus an outer bank, selected through `$4100`/`$4101`.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Sachen137 {
    prg: Vec<u8>,
    chr: Vec<u8>,
    cmd: u8,
    chr_banks: [u8; 4],
    chr_outer: u8,
    prg_bank: u8,
    horizontal: bool,
}

impl Sachen137 {
    fn new(prg: Vec<u8>, chr: Vec<u8>, header: Header) -> Self {
        Self {
            prg,
            chr,
            cmd: 0,
            chr_banks: [0; 4],
            chr_outer: 0,
            prg_bank: 0,
            horizontal: header.mirroring == Mirroring::Horizontal,
        }
    }
}

impl Mapper for Sachen137 {
    fn low_window(&self) -> Option<(u16, u16)> {
        // Registers are write-only; keep the window from floating into CPU reads.
        Some((0x4100, 0x4101))
    }

    fn prg_read(&self, address: u16) -> u8 {
        if address < 0x8000 {
            return 0;
        }
        let banks = (self.prg.len() / 0x8000).max(1);
        let bank = usize::from(self.prg_bank) % banks;
        self.prg
            .get(bank * 0x8000 + usize::from(address & 0x7FFF))
            .copied()
            .unwrap_or(0)
    }

    fn prg_write(&mut self, address: u16, value: u8) {
        match address {
            0x4100 => self.cmd = value & 0x07,
            0x4101 => match self.cmd {
                0..=3 => self.chr_banks[usize::from(self.cmd)] = value & 0x07,
                4 => self.chr_outer = value & 0x07,
                5 => self.prg_bank = value & 0x07,
                7 => self.horizontal = value & 0x01 != 0,
                _ => {}
            },
            _ => {}
        }
    }

    fn chr_read(&self, address: u16) -> u8 {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = (usize::from(self.chr_banks[slot]) | (usize::from(self.chr_outer) << 4)) % banks;
        self.chr
            .get(bank * 0x800 + usize::from(address & 0x07FF))
            .copied()
            .unwrap_or(0)
    }

    fn chr_write(&mut self, address: u16, value: u8) {
        let banks = (self.chr.len() / 0x800).max(1);
        let slot = usize::from((address >> 11) & 0x03);
        let bank = (usize::from(self.chr_banks[slot]) | (usize::from(self.chr_outer) << 4)) % banks;
        if let Some(byte) = self
            .chr
            .get_mut(bank * 0x800 + usize::from(address & 0x07FF))
        {
            *byte = value;
        }
    }

    fn mirroring(&self) -> Mirroring {
        if self.horizontal {
            Mirroring::Horizontal
        } else {
            Mirroring::Vertical
        }
    }

    fn number(&self) -> u16 {
        137
    }

    fn chr_mapping_write(&self, address: u16) -> bool {
        address == 0x4100 || address == 0x4101
    }
}

