    #[test]
    fn mapper547_qtram_selects_chr_rom_ram_and_shadow_nametables() {
        let rom = synth_banked(547, 640, 128);
        let cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 547);
        let qt = cart.qtram().expect("qtram");
        let chr_base = 16 + 640 * 1024;
        {
            let mut state = qt.borrow_mut();
            // Tile byte $41: CHR-ROM page 1, low half filled with $00.
            state.qt = 0x41;
            state.sprite = false;
        }
        // 128 KiB CHR address swizzle: page 1/offset 0 -> byte $800.
        assert_eq!(cart.ppu_read(0x0000), rom[chr_base + 0x800]);
        assert_eq!(cart.ppu_read(0x0008), 0x00);
        {
            let mut state = qt.borrow_mut();
            state.qt = 0xC1;
        }
        assert_eq!(cart.ppu_read(0x0008), 0xFF);
        {
            let mut state = qt.borrow_mut();
            // No CHR-ROM bit: background fetches use 4 KiB CHR-RAM bank 1,
            // sprite fetches keep the normal $D005-banked window.
            state.qt = 0x01;
            state.sprite = false;
        }
        assert_eq!(cart.ppu_read(0x0000), rom[chr_base + 0x1000]);
        qt.borrow_mut().sprite = true;
        assert_eq!(cart.ppu_read(0x0000), rom[chr_base]);
        // The PPU latches `qt` from the shadow name table.
        {
            let mut state = qt.borrow_mut();
            state.ram[0] = 0x55;
            state.horizontal = false;
        }
        qt.borrow_mut().note_read(0x2000);
        assert_eq!(qt.borrow().qt, 0x55);
    }

    #[test]
    fn mapper547_prg_chr_wram_and_irq() {
        // 640 KiB PRG (80 x 8 KiB), 128 KiB CHR.
        let rom = synth_banked(547, 640, 128);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 547);
        // Power-on PRG registers map internal bank 0 and the last external bank.
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xC000), rom[16]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x4F * 0x2000]);
        // $D200 bit 6 selects the external 512 KiB chip (bank $10 onward).
        cart.cpu_write(0xD200, 0x40);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x10 * 0x2000]);
        cart.cpu_write(0xD400, 0x01);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x2000]);
        // $D000 selects the 4 KiB work-RAM bank at $6000.
        cart.cpu_write(0x6000, 0x5A);
        assert_eq!(cart.cpu_read(0x6000), 0x5A);
        cart.cpu_write(0xD000, 0x01);
        assert_eq!(cart.cpu_read(0x6000), 0x00);
        cart.cpu_write(0x7000, 0x11);
        assert_eq!(cart.cpu_read(0x7000), 0x11);
        // Background CHR now comes from the Q-Ta shadow name table byte;
        // $D500 still supplies the sprite window.
        cart.cpu_write(0xD500, 0x01);
        let qt = cart.qtram().expect("qtram");
        qt.borrow_mut().qt = 0x01;
        let chr = 16 + 640 * 1024;
        assert_eq!(cart.ppu_read(0x0000), rom[chr + 0x1000]);
        assert_eq!(cart.ppu_read(0x1000), rom[chr + 0x1000]);
        cart.cpu_write(0xD500, 0x00);
        qt.borrow_mut().qt = 0x00;
        assert_eq!(cart.ppu_read(0x0000), rom[chr]);
        // $DA00 bit 1 selects horizontal mirroring.
        assert_eq!(cart.mirroring(), Mirroring::Vertical);
        cart.cpu_write(0xDA00, 0x02);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
        // Cycle IRQ: enable with a zero latch, then wrap a 16-bit counter.
        cart.cpu_write(0xD600, 0x00);
        cart.cpu_write(0xD700, 0x00);
        cart.cpu_write(0xD900, 0x02);
        for _ in 0..=0xFFFF {
            cart.clock_cpu();
        }
        assert!(cart.irq_line());
        cart.acknowledge_irq();
        assert!(!cart.irq_line());
    }

    #[test]
    fn mapper594_outer_banks_prg_rom_and_fifo() {
        // 1 MiB PRG (128 x 8 KiB), 256 KiB CHR.
        let rom = synth_banked(594, 1024, 256);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 594);
        // $6000 exposes an 8 KiB PRG-ROM bank from $9000.
        assert_eq!(cart.cpu_read(0x6000), rom[16]);
        cart.cpu_write(0x9000, 5);
        assert_eq!(cart.cpu_read(0x6000), rom[16 + 5 * 0x2000]);
        // MMC3 power-on mapping: zeroed R6/R7 and the last two fixed banks.
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xA000), rom[16]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 62 * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 63 * 0x2000]);
        // $B000 bit 6 adds PRG A19 (0xC0) to every MMC3 slot.
        cart.cpu_write(0xB000, 0x40);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 64 * 0x2000]);
        // 0xFF is masked by the 128-bank image.
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x7F * 0x2000]);
        // MMC3 register writes still select banks.
        cart.cpu_write(0xB000, 0);
        cart.cpu_write(0x8000, 6);
        cart.cpu_write(0x8001, 7);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 7 * 0x2000]);
        // The FIFO status reads as "not half full".
        assert_eq!(cart.cpu_read_io(0x5000), 0x40);
        cart.cpu_write(0x5000, 0x12);
        assert_eq!(cart.cpu_read_io(0x5000), 0x40);
        // Mirroring from the MMC3 register.
        cart.cpu_write(0xA000, 1);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
    }

    #[test]
    fn rinco_msm6585_decodes_fifo_audio() {
        let rom = synth_banked(594, 1024, 256);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5001, 0); // 4 kHz
        for _ in 0..512 {
            cart.cpu_write(0x5000, 0xA5);
        }
        assert_eq!(
            cart.cpu_read_io(0x5000),
            0x00,
            "half-full FIFO must stop the CPU feeding samples"
        );
        let mut peak = 0.0f32;
        for _ in 0..200_000 {
            cart.clock_cpu();
            peak = peak.max(cart.audio_mix().abs());
        }
        assert!(peak > 0.01, "MSM6585 produced no audio (peak {peak})");
        assert!(cart.audio_mix().is_finite());
    }

    #[test]
    fn jf13_bootleg_speech_uses_the_miscellaneous_rom() {
        let mut rom = synth_banked(86, 128, 64);
        // NES 2.0 header, submapper 1 (bootleg JF-13 with speech data).
        rom[7] = (rom[7] & 0xF0) | 0x08;
        rom[8] = 0x10;
        // 32 KiB of CVSD bitstream after the CHR area.
        let mut speech = vec![0u8; 32 * 1024];
        for (index, byte) in speech.iter_mut().enumerate() {
            *byte = if index % 3 == 0 { 0xA5 } else { 0x5A };
        }
        rom.extend_from_slice(&speech);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5000, 0x00); // 88-cycle bit period
        cart.cpu_write(0x7000, 0x00); // start message 0
        let mut peak = 0.0f32;
        for _ in 0..200_000 {
            cart.clock_cpu();
            peak = peak.max(cart.audio_mix().abs());
        }
        assert!(peak > 0.001, "CVSD speech stayed silent (peak {peak})");
        assert!(cart.audio_mix().is_finite());
    }

    #[test]
    fn mapper169_computer_and_game_modes() {
        // 1 MiB PRG, CHR-RAM.
        let rom = synth_banked(169, 1024, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 169);
        // Computer mode: $8000 is a 32 KiB ROM bank selected by $4800.
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xFFFF), rom[16 + 0x7FFF]);
        cart.cpu_write(0x4800, 0x03);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 3 * 0x8000]);
        // Mirroring comes from $5500 bit 3.
        assert_eq!(cart.mirroring(), Mirroring::Vertical);
        cart.cpu_write(0x5500, 0x08);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
        // $5500 bit 2 maps PRG-RAM; $4800 bit 5 arms the bank latch.
        cart.cpu_write(0x5500, 0x04);
        cart.cpu_write(0x4800, 0x20);
        cart.cpu_write(0x8000, 3);
        cart.cpu_write(0x4800, 0x00);
        cart.cpu_write(0x8000, 0x5A);
        assert_eq!(cart.cpu_read(0x8000), 0x5A);
        // $5501 selects the 8 KiB CHR-RAM page.
        cart.cpu_write(0x5501, 0x00);
        cart.ppu_write(0x0000, 0x11);
        cart.cpu_write(0x5501, 0x04);
        assert_eq!(cart.ppu_read(0x0000), 0x00);
        cart.ppu_write(0x0000, 0x22);
        cart.cpu_write(0x5501, 0x00);
        assert_eq!(cart.ppu_read(0x0000), 0x11);
        // 1-bpp mode remaps address bit 3 from the latched PPU A0.
        cart.cpu_write(0x4800, 0x80);
        cart.ppu_write(0x0008, 0xAA);
        cart.chr169()
            .expect("chr169")
            .borrow_mut()
            .note_address(0x2001);
        assert_eq!(cart.ppu_read(0x0000), 0xAA);
        // MMC3 game mode ($5501 bit 7) takes over $8000-$FFFF.
        cart.cpu_write(0x5501, 0x80);
        cart.cpu_write(0x8000, 0x06);
        cart.cpu_write(0x8001, 0x05);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 5 * 0x2000]);
    }

    #[test]
    fn pic355_runs_protection_program() {
        // 32 KiB PRG plus a 1 KiB PIC program in the NES 2.0 Misc ROM.
        let mut rom = synth_banked(355, 32, 0);
        rom[14] = 0x01;
        let mut misc = vec![0u8; 1024];
        let mut set = |index: usize, value: u16| {
            misc[index * 2] = value as u8;
            misc[index * 2 + 1] = (value >> 8) as u8;
        };
        set(0x1FF, 0xA00); // reset vector: GOTO 0
        set(0, 0xC00); // MOVLW 0
        set(1, 0x005); // TRIS 5: port-A update asserts the IRQ line
        set(2, 0xA02); // GOTO 2
        rom.extend_from_slice(&misc);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 355);
        assert!(!cart.irq_line());
        for _ in 0..64 {
            cart.clock_cpu();
        }
        assert!(cart.irq_line());
    }

    #[test]
    fn um6578_405_windows_registers_and_dma() {
        // 1 MiB PRG, CHR-RAM.
        let rom = synth_banked(405, 1024, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 405);
        // Power-on windows are linear 4 KiB banks 0..7.
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0x9000), rom[16 + 0x1000]);
        assert_eq!(cart.cpu_read(0xF000), rom[16 + 7 * 0x1000]);
        cart.cpu_write(0x4040, 5);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 5 * 0x1000]);
        // The bank registers are readable.
        assert_eq!(cart.cpu_read_io(0x4040), 5);
        cart.cpu_write(0x4041, 2);
        assert_eq!(cart.cpu_read(0x9000), rom[16 + 2 * 0x1000]);
        // 2 KiB at $5000 and 8 KiB at $6000.
        cart.cpu_write(0x5000, 0x33);
        assert_eq!(cart.cpu_read_io(0x5000), 0x33);
        cart.cpu_write(0x6000, 0x5A);
        assert_eq!(cart.cpu_read(0x6000), 0x5A);
        // DMA request: RAM $0000 -> PPU $2000, 4 bytes.
        cart.cpu_write(0x4048, 0x80);
        cart.cpu_write(0x404A, 0x00);
        cart.cpu_write(0x404B, 0x00);
        cart.cpu_write(0x404C, 0x00);
        cart.cpu_write(0x404D, 0x20);
        cart.cpu_write(0x404E, 0x04);
        cart.cpu_write(0x404F, 0x00);
        let request = cart.take_dma().expect("dma");
        assert!(request.to_ppu);
        assert!(!request.source_rom);
        assert_eq!(request.source, 0);
        assert_eq!(request.target, 0x2000);
        assert_eq!(request.len, 4);
        assert!(cart.take_dma().is_none());
        assert!(cart.um6578());
        assert_eq!(cart.prg_linear(0), rom[16]);
    }

    #[test]
    fn subor_sango_559_banks_and_nametables() {
        // 256 KiB PRG and CHR.
        let rom = synth_banked(559, 256, 256);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 559);
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 30 * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 31 * 0x2000]);
        cart.cpu_write(0x8000, 2);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 2 * 0x2000]);
        // $9C00 selects the switchable $C000 bank; bit 2 selects the NT regs.
        cart.cpu_write(0x9C00, 5);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 5 * 0x2000]);
        assert_eq!(
            cart.rom_nametable_quadrants(),
            Some([0xE0, 0xE0, 0xE1, 0xE1])
        );
        cart.cpu_write(0x9C04, 1);
        assert_eq!(cart.rom_nametable_quadrants(), Some([1, 0xE0, 0xE1, 0xE1]));
        cart.cpu_write(0x9000, 1);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
        // CHR is 1 KiB banked with our test image's bank 3.
        cart.cpu_write(0xB000, 3);
        let chr = 16 + 256 * 1024;
        assert_eq!(cart.ppu_read(0x0000), rom[chr + 3 * 0x400]);
        assert!(cart.has_rom_nametables());
    }

    #[test]
    fn j2020_563_banks_and_a12_irq() {
        // 256 KiB PRG and CHR.
        let rom = synth_banked(563, 256, 256);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 563);
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 30 * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 31 * 0x2000]);
        cart.cpu_write(0x8000, 5);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 5 * 0x2000]);
        cart.cpu_write(0x9000, 1);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
        cart.cpu_write(0xB000, 0x0A);
        cart.cpu_write(0xB001, 0x01);
        let chr = 16 + 256 * 1024;
        assert_eq!(cart.ppu_read(0x0000), rom[chr + 0x1A * 0x400]);
        // A12 falling edges count down to an IRQ every 16 edges.
        cart.cpu_write(0xF008, 0);
        {
            let aux = cart.a12_irq().expect("a12");
            for _ in 0..16 {
                aux.borrow_mut().observe(0x1000);
                aux.borrow_mut().observe(0x0000);
            }
        }
        assert!(cart.irq_line());
        cart.cpu_write(0xF00C, 0);
        assert!(!cart.irq_line());
    }

