    #[test]
    fn hsk007_394_outer_slices() {
        // 1 MiB PRG and CHR, submapper 0.
        let rom = synth_banked(394, 1024, 1024);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 394);
        let p = |n: usize| rom[16 + n * 0x2000];
        // Power-on $5009 = $0F: MMC3 mode in the last 256 KiB slice.
        assert_eq!(cart.cpu_read(0x8000), p(96));
        assert_eq!(cart.cpu_read(0xC000), p(126));
        assert_eq!(cart.cpu_read(0xE000), p(127));
        let chr = 16 + 1024 * 1024;
        let c = |n: usize| rom[chr + n * 0x400];
        assert_eq!(cart.ppu_read(0x0000), c(768));
        // MMC3 CHR registers stay inside the CHR slice (R0 is a 2 KiB bank).
        cart.cpu_write(0x8000, 0);
        cart.cpu_write(0x8001, 3);
        assert_eq!(cart.ppu_read(0x0000), c(770));
        // BNROM mode: one 32 KiB bank built from both registers.
        cart.cpu_write(0x5009, 0x07);
        cart.cpu_write(0x500B, 0x90);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 24 * 0x8000]);
        // Back to MMC3 mode.
        cart.cpu_write(0x5009, 0x0B);
        assert_eq!(cart.cpu_read(0xE000), p(127));
    }

    #[test]
    fn multibank_334_prg_register() {
        // 128 KiB PRG (4 x 32 KiB), 128 KiB CHR.
        let rom = synth_banked(334, 128, 128);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 334);
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xFFFF), rom[16 + 0x7FFF]);
        // The register only latches once MMC3 WRAM is enabled.
        cart.cpu_write(0xA001, 0x00);
        cart.cpu_write(0x6000, 0x08);
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        cart.cpu_write(0xA001, 0x80);
        cart.cpu_write(0x6000, 0x08);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 2 * 0x8000]);
        assert_eq!(cart.cpu_read(0xFFFF), rom[16 + 3 * 0x8000 - 1]);
        // Jumper register reads as the 5-in-1 setting.
        assert_eq!(cart.cpu_read(0x6002), 0x01);
        // MMC3 still provides CHR banking and mirroring.
        cart.cpu_write(0x8000, 0);
        cart.cpu_write(0x8001, 3);
        // MMC3 R0 is a 2 KiB bank, so slot 0 resolves to even bank 2.
        assert_eq!(cart.ppu_read(0x0000), 0x82);
        cart.cpu_write(0xA000, 1);
        assert_eq!(cart.mirroring(), Mirroring::Horizontal);
    }

    #[test]
    fn one_bus_256_single_space_and_registers() {
        // 512 KiB PRG and no CHR ROM: CHR reads come from the PRG space.
        let rom = synth_banked(256, 512, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 256);
        assert!(!cart.chr_is_ram());
        cart.cpu_write(0x8000, 0x00);
        cart.cpu_write(0x8001, 0x20);
        assert_eq!(cart.ppu_read(0x0000), rom[16 + 0x20 * 0x400]);
        // PS=5 masks inner bit 0; PQ3 supplies the remaining bank bits
        // without shifting.
        cart.cpu_write(0x410B, 0x05);
        cart.cpu_write(0x410A, 0x1B);
        cart.cpu_write(0x4107, 0x01);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x1B * 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x1A * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x1B * 0x2000]);
        // COMR6 swaps the even $8000/$C000 slots.
        cart.cpu_write(0x4105, 0x40);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x1A * 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x1B * 0x2000]);
        // Submapper 1 (Waixing VT03) swaps the $2012-$2017 CHR registers.
        let mut rom1 = synth_banked(256, 128, 64);
        rom1[8] = 0x11;
        let mut cart1 = Cartridge::from_ines(&rom1).expect("cart");
        cart1.native_ppu_write(0x2012, 0x20);
        assert_eq!(cart1.ppu_read(0x1400), rom1[16 + 128 * 1024 + 0x20 * 0x400]);
        assert_eq!(cart1.ppu_read(0x1000), rom1[16 + 128 * 1024]);
    }

    #[test]
    fn supervisor_446_submapper3_h3001_tail() {
        // 1 MiB image: submapper 3 boots with the low $1E/$1F window.
        let mut rom = synth_banked(446, 1024, 0);
        rom[8] = (rom[8] & 0x0F) | (3 << 4);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 446);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x1E * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x1F * 0x2000]);
        // Locking with fuse 1 selects H3001; $5001/$5003 offset and mask its
        // four 8 KiB banks.
        cart.cpu_write(0x5003, 0xE0); // stored inverted as $1F
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x81);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x20 * 0x2000]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x21 * 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x3E * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x3F * 0x2000]);
        // Register writes are ignored once locked.
        cart.cpu_write(0x5001, 0);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x20 * 0x2000]);
    }

    #[test]
    fn supervisor_446_skrom_and_chr_ram() {
        // 512 KiB PRG, CHR-RAM, submapper 0 (SKROM / MMC1).
        let rom = synth_banked(446, 512, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 446);
        // Unlocked fixed mapping: $8000/$A000 = 0/1, $C000/$E000 = $3E/$3F.
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x3E * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x3F * 0x2000]);
        // $5001 pages the first two 8 KiB windows.
        cart.cpu_write(0x5001, 3);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 3 * 0x2000]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 4 * 0x2000]);
        // CHR-RAM is banked by $5006 in 8 KiB pages.
        cart.ppu_write(0x0000, 0x5A);
        assert_eq!(cart.ppu_read(0x0000), 0x5A);
        cart.cpu_write(0x5006, 1);
        assert_eq!(cart.ppu_read(0x0000), 0);
        cart.cpu_write(0x5006, 0);
        assert_eq!(cart.ppu_read(0x0000), 0x5A);
        // $5005 bit 4 protects CHR-RAM.
        cart.cpu_write(0x5005, 0x10);
        cart.ppu_write(0x0001, 0x77);
        assert_eq!(cart.ppu_read(0x0001), 0);
        cart.cpu_write(0x5005, 0x00);
        cart.ppu_write(0x0001, 0x77);
        assert_eq!(cart.ppu_read(0x0001), 0x77);
    }

    #[test]
    fn supervisor_446_locked_latch_boards() {
        // 512 KiB PRG, 256 KiB CHR, submapper 0.
        let rom = synth_banked(446, 512, 256);
        // Fuse 0 -> UNROM. $0F/8K becomes a 16 KiB mask of 7; outer $20
        // becomes a 16 KiB base of $10.
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0);
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x80);
        cart.cpu_write(0x8000, 3);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x13 * 0x4000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x17 * 0x4000]);
        // Fuse 3 -> CNROM: four fixed 8 KiB slots in the $20 window.
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0);
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x83);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x20 * 0x2000]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x21 * 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x22 * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x23 * 0x2000]);
        // Fuse 15 -> 189. The fused $6000 latch selects 32 KiB banks in the
        // $20 window.
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0);
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x8F);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 8 * 0x8000]);
        cart.cpu_write(0x6000, 0x01);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 9 * 0x8000]);
    }

    #[test]
    fn supervisor_446_locked_mmc3_and_vrc_mask() {
        // 512 KiB PRG, 256 KiB CHR, submapper 0.
        let rom = synth_banked(446, 512, 256);
        // Fuse 4 -> MMC3. Mask $0F and outer base $20 apply to every slot.
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0); // stored inverted as $0F
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x84);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x20 * 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x2E * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x2F * 0x2000]);
        cart.cpu_write(0x8000, 0x06);
        cart.cpu_write(0x8001, 0x03);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x23 * 0x2000]);
        // Fuse 8 -> VRC4: the same mask/outer applies to its page registers.
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0);
        cart.cpu_write(0x5001, 0x20);
        cart.cpu_write(0x5000, 0x88);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 0x2E * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 0x2F * 0x2000]);
        cart.cpu_write(0x8000, 0x03);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x23 * 0x2000]);
    }

    #[test]
    fn supervisor_446_locked_snrom_masking() {
        // Submapper 0, 512 KiB: fuse 1 locks to SNROM (MMC1). The supervisor
        // applies its 8 KiB mask to the MMC1's 16 KiB page, so a mask of
        // $0F turns the fixed $C000 page into bank 7 (8K banks 14/15).
        let rom = synth_banked(446, 512, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x5003, 0xF0); // stored inverted as $0F
        cart.cpu_write(0x5001, 0x00);
        cart.cpu_write(0x5000, 0x81);
        assert_eq!(cart.cpu_read(0x8000), rom[16]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x2000]);
        assert_eq!(cart.cpu_read(0xC000), rom[16 + 14 * 0x2000]);
        assert_eq!(cart.cpu_read(0xE000), rom[16 + 15 * 0x2000]);
        // The indirect entry vector now reads from the masked fixed page.
        assert_eq!(cart.cpu_read(0xFFFC), rom[16 + 15 * 0x2000 + 0x1FFC]);
    }

    #[test]
    fn supervisor_446_submapper2_outer_bank() {
        let mut rom = synth_banked(446, 512, 0);
        rom[8] = (rom[8] & 0x0F) | (2 << 4);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 446);
        // Unlocked, $5001 pages the first two windows; $5003 is not used yet.
        cart.cpu_write(0x5003, 0);
        cart.cpu_write(0x5001, 1);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x2000]);
        assert_eq!(cart.cpu_read(0xA000), rom[16 + 0x4000]);
        cart.cpu_write(0x5003, 0xFF);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 0x2000]);
        // Fuse 9 locks submapper 2 to an MMC3 inner board.
        cart.cpu_write(0x5000, 0x89);
        cart.cpu_write(0x8000, 0x06);
        cart.cpu_write(0x8001, 0x03);
        assert_eq!(cart.cpu_read(0x8000), rom[16 + 3 * 0x2000]);
    }

    #[test]
    fn reset_mc_374_windows() {
        // 512 KiB PRG and CHR: four 128 KiB game slots.
        let rom = synth_banked(374, 512, 512);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 374);
        let p = |n: usize| rom[16 + n * 0x4000];
        let c = |n: usize| rom[16 + 512 * 1024 + n];
        assert_eq!(cart.cpu_read(0x8000), p(0));
        assert_eq!(cart.cpu_read(0xC000), p(7));
        assert_eq!(cart.ppu_read(0x0000), c(0));
        cart.soft_reset();
        // A reset advances to the next 128 KiB PRG/CHR slot.
        assert_eq!(cart.cpu_read(0x8000), p(8));
        assert_eq!(cart.cpu_read(0xC000), p(15));
        assert_eq!(cart.ppu_read(0x0000), c(0x2_0000));
        cart.soft_reset();
        cart.soft_reset();
        cart.soft_reset();
        // Four slots wrap back to the first.
        assert_eq!(cart.cpu_read(0x8000), p(0));
        assert_eq!(cart.ppu_read(0x0000), c(0));
    }

