    #[test]
    fn mmc3_chr_ram_map_follows_the_bank_registers() {
        // 128 KiB PRG, CHR-RAM: mapper 4.
        let rom = synth_banked(4, 128, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 4);
        // Power-on: the two 2 KiB pairs select 1 KiB banks 0/1 each, and the
        // four single-slot registers are zero.
        assert_eq!(cart.chr_ram_map(), Some([0, 1, 0, 1, 0, 0, 0, 0]));
        cart.cpu_write(0x8000, 0x00);
        cart.cpu_write(0x8001, 0x04); // R0 -> slots 0/1 = 4/5.
        cart.cpu_write(0x8000, 0x02);
        cart.cpu_write(0x8001, 0x06); // R2 -> slot 4 = 6.
        assert_eq!(cart.chr_ram_map(), Some([4, 5, 0, 1, 6, 0, 0, 0]));
        // 4 KiB mode: R2-R5 fill the first four slots and R0/R1 the pairs.
        cart.cpu_write(0x8000, 0x80);
        assert_eq!(cart.chr_ram_map(), Some([6, 0, 0, 0, 4, 5, 0, 1]));
    }

    #[test]
    fn mmc1_ignores_a_serial_write_on_the_next_cycle() {
        // 256 KiB PRG (16 x 16 KiB), CHR-RAM: bank 9 must exist.
        let rom = synth_banked(1, 256, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        // The `INC $addr` reset trick: the dummy $FF write resets the chip and
        // the real $00 write on the next cycle must be dropped.
        cart.set_cpu_cycle(100);
        cart.cpu_write(0xFFFF, 0xFF);
        cart.set_cpu_cycle(101);
        cart.cpu_write(0xFFFF, 0x00);
        // Five properly spaced bits latch PRG bank 9.
        for (i, value) in [0x09u8, 0x04, 0x02, 0x01, 0x00].into_iter().enumerate() {
            cart.set_cpu_cycle(200 + i as u64 * 4);
            cart.cpu_write(0xE000, value);
        }
        assert_eq!(cart.cpu_read(0x8000), 18, "16 KiB bank 9");
        // Reading the same value back after another write confirms the latch.
        cart.cpu_write(0x8000, 0x00);
        assert_eq!(cart.cpu_read(0x8000), 18);
    }

    #[test]
    fn mmc1_surom_chr_bit4_selects_the_prg_half() {
        // 512 KiB PRG (32 x 16 KiB), CHR-RAM: SUROM wiring.
        let rom = synth_banked(1, 512, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        // Mode 3 (power-on control from the header): bank 0 at $8000, the last
        // bank of the low 256 KiB half at $C000.
        assert_eq!(cart.cpu_read(0x8000), 0);
        assert_eq!(cart.cpu_read(0xC000), 30);
        // Serial-write $10 into CHR register 0: bit 4 selects the upper half.
        for value in [0u8, 0, 0, 0, 1] {
            cart.cpu_write(0xA000, value);
        }
        assert_eq!(cart.cpu_read(0x8000), 32);
        assert_eq!(cart.cpu_read(0xC000), 62);
    }

    #[test]
    fn mmc1_e000_bit4_disables_prg_ram() {
        // 128 KiB PRG, CHR-RAM: MMC1 with an 8 KiB PRG-RAM window.
        let rom = synth_banked(1, 128, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0x6000, 0x5A);
        assert_eq!(cart.cpu_read(0x6000), 0x5A);
        // Serial-write $10 to $E000: five LSB-first writes with bit 0.
        for value in [0u8, 0, 0, 0, 1] {
            cart.cpu_write(0xE000, value);
        }
        // Bit 4 deselects the RAM, so the window floats.
        assert_eq!(cart.cpu_read(0x6000), 0xFF);
        cart.cpu_write(0x6000, 0x99);
        assert_eq!(cart.cpu_read(0x6000), 0xFF);
        // Clear the bit again.
        for value in [0u8, 0, 0, 0, 0] {
            cart.cpu_write(0xE000, value);
        }
        assert_eq!(cart.cpu_read(0x6000), 0x5A);
    }

    #[test]
    fn nes2_sizes_use_the_twelve_bit_form() {
        // Ordinary form: the MSB nibble extends the byte to 12 bits.
        assert_eq!(nes2_size(0x80, 0, 16), 2 * 1024 * 1024);
        assert_eq!(nes2_size(0, 1, 8), 2 * 1024 * 1024);
        assert_eq!(nes2_size(3, 0, 8), 3 * 8 * 1024);
        // $0F selects the exponent-multiplier form instead.
        // EE = 3 (x8) and MM = 3 (x7) -> 56 units of 16 KiB.
        assert_eq!(nes2_size(0x0F, 0x0F, 16), 56 * 16 * 1024);
    }

    #[test]
    fn ks7032_exposes_prg_rom_at_6000() {
        // 128 KiB PRG (16 x 8 KiB), CHR-RAM.
        let rom = synth_banked(142, 128, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        assert_eq!(cart.mapper(), 142);
        // The CPU bus must forward the window even without PRG-RAM.
        assert!(cart.prg_rom_at_6000());
        // $E000 = 4 selects register 3, $F000 = 2 points the window at
        // 8 KiB bank 2 (the reset vector still lives in the fixed last bank).
        cart.cpu_write(0xE000, 4);
        cart.cpu_write(0xF000, 2);
        assert_eq!(cart.cpu_read(0x6000), 2);
        assert_eq!(cart.cpu_read(0xE000), 15);
    }

    #[test]
    fn ks7032_banks_and_irq() {
        let rom = synth_banked(142, 128, 0);
        let mut cart = Cartridge::from_ines(&rom).expect("cart");
        cart.cpu_write(0xE000, 1);
        cart.cpu_write(0xF000, 2);
        cart.cpu_write(0xE000, 2);
        cart.cpu_write(0xF000, 3);
        cart.cpu_write(0xE000, 4);
        cart.cpu_write(0xF000, 5);
        assert_eq!(cart.cpu_read(0x8000), 2);
        assert_eq!(cart.cpu_read(0xA000), 3);
        assert_eq!(cart.cpu_read(0x6000), 5);
        assert_eq!(cart.cpu_read(0xE000), 15);
        cart.cpu_write(0x8000, 0x0E);
        cart.cpu_write(0x8001, 0x0F);
        cart.cpu_write(0x8002, 0x0F);
        cart.cpu_write(0x8003, 0x0F);
        cart.cpu_write(0xC000, 0x02);
        // The KS7032 counts up from the reload value and fires when it wraps
        // back to $FFFF, so a $FFFF reload is the longest period.
        let mut cycles = 0u32;
        while !cart.irq_line() && cycles < 70_000 {
            cart.clock_cpu();
            cycles += 1;
        }
        assert!(cart.irq_line(), "IRQ never asserted");
        assert!(cycles <= 65_536);
    }

