        assert_eq!(cart.cpu_read(0xC000), 6);
        cart.cpu_write(0x8000, 0x40);
        assert_eq!(cart.cpu_read(0x8000), 2);

        // $C000 reloads the 1024-cycle counter and clears the line.
        cart.cpu_write(0xC000, 0);
